screenPanels.initJs:
function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => {
      const transactionType = r.入出庫区分 || "不明";
      const typeColor = transactionType === "入庫" ? "#22c55e" : transactionType === "出庫" ? "#f59e0b" : "#6b7280";
      const quantity = r.数量 || 0;
      const displayQuantity = transactionType === "出庫" ? Math.abs(quantity) : quantity;

      return `<tr data-id="${r.履歴ID || r.id || ''}">
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">
          ${r.処理日時 ? new Date(r.処理日時).toLocaleString('ja-JP', {month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit'}) : ''}
        </td>
        <td style="padding: 8px 12px; font-size: 13px; border-bottom: 1px solid var(--border);">
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 500; background: ${typeColor}20; color: ${typeColor};">
            ${transactionType}
          </span>
        </td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${r.商品名 || ''}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${r.倉庫名 || ''}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border); text-align: right; font-weight: 500;">
          ${displayQuantity}
        </td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text-muted); border-bottom: 1px solid var(--border);">${r.処理者名 || ''}</td>
        <td style="padding: 8px 12px; font-size: 13px; border-bottom: 1px solid var(--border);">
          <button class="action-btn secondary delete-btn" data-id="${r.履歴ID || r.id || ''}" style="font-size: 11px; padding: 4px 8px;">削除</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ描画とAPI呼び出し
  const historyTable = tables.find(t => t.tableName === "入出庫履歴") || tables[4] || { records: [] };
  renderHistoryRows(historyTable.records || []);

  // 最新データを取得
  window.aivicApi.list(4).then(rows => {
    if (rows) renderHistoryRows(rows);
  });

  // 3. KPI更新
  function updateKPIs() {
    window.aivicApi.list(3).then(stockRows => { // 在庫テーブル
      if (stockRows) {
        container.querySelector("#total-items").textContent = stockRows.length;
        const reorderCount = stockRows.filter(s => (s.現在庫数 || 0) <= (s.発注点 || 0)).length;
        container.querySelector("#reorder-items").textContent = reorderCount;
      }
    });

    window.aivicApi.list(4).then(historyRows => { // 入出庫履歴テーブル
      if (historyRows) {
        const today = new Date().toISOString().slice(0, 10);
        const todayRecords = historyRows.filter(r => r.処理日時 && r.処理日時.startsWith(today));
        const inboundCount = todayRecords.filter(r => r.入出庫区分 === "入庫").length;
        const outboundCount = todayRecords.filter(r => r.入出庫区分 === "出庫").length;

        container.querySelector("#today-inbound").textContent = inboundCount;
        container.querySelector("#today-outbound").textContent = outboundCount;
      }
    });
  }
  updateKPIs();

  // 4. 商品選択時の在庫数更新
  container.querySelector("#product-select").addEventListener("change", function() {
    const productId = this.value;
    const warehouseId = container.querySelector("#warehouse-select").value;

    if (productId && warehouseId) {
      window.aivicApi.list(3).then(stockRows => { // 在庫テーブル
        if (stockRows) {
          const stock = stockRows.find(s => s.商品ID === productId && s.倉庫ID === warehouseId);
          container.querySelector("#current-stock").value = stock ? (stock.現在庫数 || 0) : 0;
        }
      });
    }
  });

  container.querySelector("#warehouse-select").addEventListener("change", function() {
    const productId = container.querySelector("#product-select").value;
    const warehouseId = this.value;

    if (productId && warehouseId) {
      window.aivicApi.list(3).then(stockRows => { // 在庫テーブル
        if (stockRows) {
          const stock = stockRows.find(s => s.商品ID === productId && s.倉庫ID === warehouseId);
          container.querySelector("#current-stock").value = stock ? (stock.現在庫数 || 0) : 0;
        }
      });
    }
  });

  // 5. 検索機能
  container.querySelector("#btn-search").addEventListener("click", function() {
    const keyword = container.querySelector("#search-input").value.toLowerCase();
    window.aivicApi.list(4).then(rows => {
      if (rows) {
        const filtered = rows.filter(r => 
          JSON.stringify(r).toLowerCase().includes(keyword)
        );
        renderHistoryRows(filtered);
      }
    });
  });

  // 6. 登録ボタン
  container.querySelector("#btn-register").addEventListener("click", async function() {
    const transactionType = container.querySelector('input[name="transaction-type"]:checked')?.value;
    const productId = container.querySelector("#product-select").value;
    const warehouseId = container.querySelector("#warehouse-select").value;
    const quantity = parseInt(container.querySelector("#quantity-input").value) || 0;
    const datetime = container.querySelector("#transaction-datetime").value;
    const notes = container.querySelector("#notes-textarea").value;

    if (!transactionType || !productId || !warehouseId || !quantity || !datetime) {
      alert("必須項目を入力してください");
      return;
    }

    const currentStock = parseInt(container.querySelector("#current-stock").value) || 0;
    const adjustedQuantity = transactionType === "出庫" ? -quantity : quantity;
    const newStock = currentStock + adjustedQuantity;

    if (transactionType === "出庫" && newStock < 0) {
      alert("在庫数が不足しています");
      return;
    }

    // 入出庫履歴を登録
    const historyData = {
      商品ID: productId,
      倉庫ID: warehouseId,
      入出庫区分: transactionType,
      数量: adjustedQuantity,
      処理前在庫数: currentStock,
      処理後在庫数: newStock,
      理由コード: transactionType,
      備考: notes,
      処理日時: datetime,
      処理者ID: "current-user-id"
    };

    const saved = await window.aivicApi.save(4, historyData);
    if (saved) {
      // 在庫数を更新
      const stockRows = await window.aivicApi.list(3);
      if (stockRows) {
        const stock = stockRows.find(s => s.商品ID === productId && s.倉庫ID === warehouseId);
        if (stock) {
          await window.aivicApi.update(3, stock.在庫ID || stock.id, { 現在庫数: newStock });
        }
      }

      // フォームクリア
      container.querySelector("#product-select").value = "";
      container.querySelector("#warehouse-select").value = "";
      container.querySelector("#quantity-input").value = "";
      container.querySelector("#notes-textarea").value = "";
      container.querySelector("#current-stock").value = "";

      // 履歴再読み込み
      window.aivicApi.list(4).then(rows => {
        if (rows) renderHistoryRows(rows);
      });

      updateKPIs();
      alert("登録が完了しました");
    }
  });

  // 7. クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", function() {
    container.querySelector("#product-select").value = "";
    container.querySelector("#warehouse-select").value = "";
    container.querySelector("#quantity-input").value = "";
    container.querySelector("#notes-textarea").value = "";
    container.querySelector("#current-stock").value = "";
    container.querySelector("#barcode-input").value = "";
    container.querySelector('input[name="transaction-type"][value="入庫"]').checked = true;
  });

  // 8. 削除機能（イベントデリゲーション）
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この履歴を削除しますか？")) return;

      const historyId = deleteBtn.dataset.id;
      await window.aivicApi.delete(4, historyId);

      window.aivicApi.list(4).then(rows => {
        if (rows) renderHistoryRows(rows);
      });
      updateKPIs();
    }
  });

  // 9. 現在日時をデフォルト設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector("#transaction-datetime").value = now.toISOString().slice(0, 16);

  // 10. バーコードスキャン機能
  container.querySelector("#barcode-input").addEventListener("keypress", function(e) {
    if (e.key === "Enter") {
      const barcode = this.value;
      // 商品コードでマッチング
      window.aivicApi.list(1).then(productRows => { // 商品マスタ
        if (productRows) {
          const product = productRows.find(p => p.商品コード === barcode);
          if (product) {
            container.querySelector("#product-select").value = product.商品ID || product.id;
            container.querySelector("#product-select").dispatchEvent(new Event('change'));
          } else {
            alert("商品が見つかりません");
          }
        }
      });
      this.value = "";
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#inventory-tbody');
  const modal = container.querySelector('#new-inventory-modal');

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const variance = (r.実地在庫数 || 0) - (r.帳簿在庫数 || 0);
      const varianceClass = variance > 0 ? 'style="color: #00a86b;"' : variance < 0 ? 'style="color: #dc3545;"' : '';
      const statusBadge = getStatusBadge(r.ステータス || '実施中');

      return `
        <tr data-id="${r.id}">
          <td>${r.id ? r.id.substring(0, 8) : ''}</td>
          <td>${r.倉庫ID || ''}</td>
          <td>${r.商品ID || ''}</td>
          <td style="text-align: right;">${(r.帳簿在庫数 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(r.実地在庫数 || 0).toLocaleString()}</td>
          <td style="text-align: right;" ${varianceClass}>${variance > 0 ? '+' : ''}${variance.toLocaleString()}</td>
          <td>${r.棚卸実施日 ? new Date(r.棚卸実施日).toLocaleDateString() : ''}</td>
          <td>${r.実施者ID || ''}</td>
          <td>${statusBadge}</td>
          <td>
            <button class="action-btn secondary" style="font-size: 11px; padding: 4px 8px; margin-right: 4px;" onclick="window.showScreen('scr-1780995505965')">実績入力</button>
            <button class="action-btn secondary" style="font-size: 11px; padding: 4px 8px; margin-right: 4px;" onclick="window.showScreen('scr-1780995516133')">差異分析</button>
            <button class="action-btn secondary delete-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(rows);
  }

  function getStatusBadge(status) {
    const badges = {
      '実施中': '<span style="background: #ff6a00; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">実施中</span>',
      '完了': '<span style="background: #00a86b; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">完了</span>',
      '承認済み': '<span style="background: var(--primary); color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">承認済み</span>',
      '差異確認中': '<span style="background: #dc3545; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">差異確認中</span>'
    };
    return badges[status] || status;
  }

  function updateSummary(rows) {
    const total = rows.length;
    const inProgress = rows.filter(r => r.ステータス === '実施中').length;
    const completed = rows.filter(r => r.ステータス === '完了' || r.ステータス === '承認済み').length;
    const variance = rows.filter(r => Math.abs((r.実地在庫数 || 0) - (r.帳簿在庫数 || 0)) > 0).length;

    container.querySelector('#total-count').textContent = total;
    container.querySelector('#in-progress-count').textContent = inProgress;
    container.querySelector('#completed-count').textContent = completed;
    container.querySelector('#variance-count').textContent = variance;
  }

  // 2. 初期データ描画
  renderRows(tables[0].records || []);

  // 3. 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const warehouse = container.querySelector('#filter-warehouse').value;
    const dateFrom = container.querySelector('#filter-date-from').value;
    const dateTo = container.querySelector('#filter-date-to').value;
    const status = container.querySelector('#filter-status').value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (warehouse && r.倉庫ID !== warehouse) return false;
      if (dateFrom && r.棚卸実施日 && new Date(r.棚卸実施日) < new Date(dateFrom)) return false;
      if (dateTo && r.棚卸実施日 && new Date(r.棚卸実施日) > new Date(dateTo)) return false;
      if (status && r.ステータス !== status) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 4. 新規棚卸作成ボタン
  container.querySelector('#btn-new-inventory').addEventListener('click', () => {
    modal.style.display = 'block';
  });

  // 5. モーダル閉じる
  container.querySelector('#btn-cancel-modal').addEventListener('click', () => {
    modal.style.display = 'none';
  });

  // 6. 棚卸保存
  container.querySelector('#btn-save-inventory').addEventListener('click', async () => {
    const warehouseId = container.querySelector('#new-warehouse').value;
    const productId = container.querySelector('#new-product').value;
    const bookStock = parseInt(container.querySelector('#new-book-stock').value) || 0;
    const actualStock = parseInt(container.querySelector('#new-actual-stock').value) || 0;
    const remarks = container.querySelector('#new-remarks').value;

    if (!warehouseId || !productId) {
      alert('倉庫と商品を選択してください');
      return;
    }

    const newInventory = {
      倉庫ID: warehouseId,
      商品ID: productId,
      帳簿在庫数: bookStock,
      実地在庫数: actualStock,
      差異数量: actualStock - bookStock,
      棚卸実施日: new Date().toISOString(),
      実施者ID: 'USER001',
      ステータス: '実施中',
      備考: remarks
    };

    const saved = await window.aivicApi.save(0, newInventory);
    if (saved) {
      modal.style.display = 'none';
      // フォームリセット
      container.querySelector('#new-warehouse').value = '';
      container.querySelector('#new-product').value = '';
      container.querySelector('#new-book-stock').value = '';
      container.querySelector('#new-actual-stock').value = '';
      container.querySelector('#new-remarks').value = '';

      // 再読み込み
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 7. CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['棚卸ID', '倉庫ID', '商品ID', '帳簿在庫数', '実地在庫数', '差異数量', '棚卸実施日', '実施者ID', 'ステータス', '備考'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.id || '',
        r.倉庫ID || '',
        r.商品ID || '',
        r.帳簿在庫数 || 0,
        r.実地在庫数 || 0,
        r.差異数量 || 0,
        r.棚卸実施日 || '',
        r.実施者ID || '',
        r.ステータス || '',
        `"${(r.備考 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `棚卸実施一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 8. 削除処理（イベントデリゲーション）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この棚卸記録を削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);

      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // モーダル外クリックで閉じる
  modal.addEventListener('click', (e) => {
    if (e.target === modal) {
      modal.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const INVENTORY_RESULTS_TABLE = 5; // 棚卸実績テーブル
  const PRODUCTS_TABLE = 1; // 商品マスタ
  const WAREHOUSES_TABLE = 2; // 倉庫マスタ
  const INVENTORY_TABLE = 3; // 在庫テーブル

  let selectedProduct = null;
  let currentStock = 0;

  // 実績一覧の再描画関数
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}">
        <td style="font-size: 12px;">${r.商品コード || ''}</td>
        <td style="font-size: 12px;">${r.商品名 || ''}</td>
        <td style="font-size: 12px; text-align: right;">${r.理論在庫数 || 0}</td>
        <td style="font-size: 12px; text-align: right;">${r.実在庫数 || 0}</td>
        <td style="font-size: 12px; text-align: right; color: ${(r.差異数 || 0) !== 0 ? '#ff6a00' : 'var(--text)'};">${r.差異数 || 0}</td>
        <td style="font-size: 12px;">${r.担当者名 || ''}</td>
        <td>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">削除</button>
        </td>
      </tr>
    `).join('');

    // 統計情報の更新
    const totalCount = results.length;
    const varianceCount = results.filter(r => (r.差異数 || 0) !== 0).length;
    container.querySelector('#total-count').textContent = totalCount;
    container.querySelector('#variance-count-total').textContent = varianceCount;
  }

  // 初期データの読み込みと表示
  window.aivicApi.list(INVENTORY_RESULTS_TABLE).then(results => {
    if (results) {
      renderResults(results);
    }
  });

  // 商品検索ボタン
  container.querySelector('#btn-search-product').addEventListener('click', async () => {
    const productCode = container.querySelector('#product-code').value.trim();
    const warehouseId = container.querySelector('#warehouse').value;

    if (!productCode) {
      alert('商品コードを入力してください');
      return;
    }

    if (!warehouseId) {
      alert('倉庫を選択してください');
      return;
    }

    // 商品マスタから商品情報を取得
    const products = await window.aivicApi.list(PRODUCTS_TABLE);
    if (!products) return;

    const product = products.find(p => p.商品コード === productCode);
    if (!product) {
      alert('商品が見つかりません');
      container.querySelector('#product-name').textContent = '商品が見つかりません';
      container.querySelector('#theoretical-stock').textContent = '-';
      selectedProduct = null;
      return;
    }

    // 在庫情報を取得
    const stocks = await window.aivicApi.list(INVENTORY_TABLE);
    if (!stocks) return;

    const stock = stocks.find(s => s.商品ID === product.id && s.倉庫ID === warehouseId);
    currentStock = stock ? (stock.現在庫数 || 0) : 0;

    // 商品情報を表示
    selectedProduct = product;
    container.querySelector('#product-name').textContent = product.商品名;
    container.querySelector('#theoretical-stock').textContent = currentStock.toLocaleString();

    // 実地棚卸数入力にフォーカス
    container.querySelector('#actual-count').focus();
  });

  // 実地棚卸数の入力で差異を自動計算
  container.querySelector('#actual-count').addEventListener('input', (e) => {
    const actualCount = parseInt(e.target.value) || 0;
    const variance = actualCount - currentStock;
    container.querySelector('#variance-count').textContent = variance.toLocaleString();

    // 差異がある場合は色を変更
    const varianceEl = container.querySelector('#variance-count');
    varianceEl.style.color = variance !== 0 ? '#ff6a00' : 'var(--text)';
  });

  // 実績登録ボタン
  container.querySelector('#btn-register').addEventListener('click', async () => {
    const inventorySession = container.querySelector('#inventory-session').value;
    const warehouseId = container.querySelector('#warehouse').value;
    const actualCount = parseInt(container.querySelector('#actual-count').value) || 0;
    const staff = container.querySelector('#staff').value;
    const notes = container.querySelector('#notes').value;

    if (!inventorySession) {
      alert('棚卸実施を選択してください');
      return;
    }

    if (!warehouseId) {
      alert('倉庫を選択してください');
      return;
    }

    if (!selectedProduct) {
      alert('商品を検索してください');
      return;
    }

    if (!staff) {
      alert('棚卸担当者を選択してください');
      return;
    }

    const variance = actualCount - currentStock;

    // 棚卸実績を保存
    const resultData = {
      棚卸実施ID: inventorySession,
      商品ID: selectedProduct.id,
      倉庫ID: warehouseId,
      商品コード: selectedProduct.商品コード,
      商品名: selectedProduct.商品名,
      理論在庫数: currentStock,
      実在庫数: actualCount,
      差異数: variance,
      担当者ID: staff,
      担当者名: staff === 'USER001' ? '田中太郎' : staff === 'USER002' ? '佐藤花子' : '鈴木次郎',
      調整済フラグ: false,
      備考: notes,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(INVENTORY_RESULTS_TABLE, resultData);
    if (saved) {
      alert('棚卸実績を登録しました');

      // フォームをクリア
      container.querySelector('#btn-clear').click();

      // 一覧を再読み込み
      const results = await window.aivicApi.list(INVENTORY_RESULTS_TABLE);
      if (results) {
        renderResults(results);
      }
    }
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#product-code').value = '';
    container.querySelector('#actual-count').value = '';
    container.querySelector('#notes').value = '';
    container.querySelector('#product-name').textContent = '商品を選択してください';
    container.querySelector('#theoretical-stock').textContent = '-';
