  container.querySelector('#count-datetime').textContent = dateTimeStr;
}

function(container, apiUrl, tables) {
  // テーブルインデックスを特定
  const varianceTableIndex = tables.findIndex(t => t.tableName === '棚卸差異');
  const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
  const warehouseTableIndex = tables.findIndex(t => t.tableName === '倉庫マスタ');

  let allVariances = [];

  // 差異一覧テーブル再描画関数
  function renderVariances(variances) {
    const tbody = container.querySelector('#variance-tbody');
    tbody.innerHTML = variances.map(v => {
      const product = tables[productTableIndex]?.records?.find(p => p.商品ID === v.商品ID) || {};
      const warehouse = tables[warehouseTableIndex]?.records?.find(w => w.倉庫ID === v.倉庫ID) || {};
      const diffAmount = (v.差異数量 || 0) * (product.標準価格 || 0);
      const diffRate = v.帳簿在庫数 > 0 ? ((v.差異数量 || 0) / v.帳簿在庫数 * 100).toFixed(1) : '0.0';

      return `
        <tr data-id="${v.棚卸差異ID || v.id}">
          <td class="text-sm">${product.商品名 || 'N/A'}</td>
          <td class="text-sm">${warehouse.倉庫名 || 'N/A'}</td>
          <td class="text-sm text-right">${(v.帳簿在庫数 || 0).toLocaleString()}</td>
          <td class="text-sm text-right">${(v.実地在庫数 || 0).toLocaleString()}</td>
          <td class="text-sm text-right ${(v.差異数量 || 0) < 0 ? 'text-red-400' : 'text-green-400'}">${(v.差異数量 || 0).toLocaleString()}</td>
          <td class="text-sm text-right ${diffAmount < 0 ? 'text-red-400' : 'text-green-400'}">¥${Math.abs(diffAmount).toLocaleString()}</td>
          <td class="text-sm">${v.差異原因 || '-'}</td>
          <td class="text-center">
            <button class="action-btn secondary text-xs detail-btn" data-id="${v.棚卸差異ID || v.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(variances);
  }

  // サマリー更新
  function updateSummary(variances) {
    const count = variances.length;
    const totalAmount = variances.reduce((sum, v) => {
      const product = tables[productTableIndex]?.records?.find(p => p.商品ID === v.商品ID) || {};
      return sum + Math.abs((v.差異数量 || 0) * (product.標準価格 || 0));
    }, 0);

    container.querySelector('#summary-count').textContent = `${count}件`;
    container.querySelector('#summary-amount').textContent = `¥${totalAmount.toLocaleString()}`;
  }

  // 差異原因分類グラフ描画
  function drawCauseChart(variances) {
    const canvas = container.querySelector('#cause-chart');
    const ctx = canvas.getContext('2d');

    // 原因別集計
    const causes = {};
    variances.forEach(v => {
      const cause = v.差異原因 || 'その他';
      causes[cause] = (causes[cause] || 0) + 1;
    });

    const entries = Object.entries(causes);
    const total = entries.reduce((sum, [, count]) => sum + count, 0);

    if (total === 0) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    // 円グラフ描画
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 20;
    const colors = ['#3b82f6', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6'];

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    let startAngle = 0;
    entries.forEach(([cause, count], index) => {
      const angle = (count / total) * 2 * Math.PI;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + angle);
      ctx.closePath();
      ctx.fillStyle = colors[index % colors.length];
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + angle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);

      ctx.fillStyle = '#ffffff';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${cause}`, labelX, labelY - 5);
      ctx.fillText(`${count}件`, labelX, labelY + 10);

      startAngle += angle;
    });
  }

  // 検索・フィルタ処理
  function performSearch() {
    const inventoryDate = container.querySelector('#select-inventory-date').value;
    const warehouse = container.querySelector('#select-warehouse').value;
    const category = container.querySelector('#select-category').value;
    const amountMin = parseFloat(container.querySelector('#input-amount-min').value) || 0;
    const amountMax = parseFloat(container.querySelector('#input-amount-max').value) || Infinity;
    const rateMin = parseFloat(container.querySelector('#input-rate-min').value) || -Infinity;
    const rateMax = parseFloat(container.querySelector('#input-rate-max').value) || Infinity;

    let filtered = allVariances.filter(v => {
      const product = tables[productTableIndex]?.records?.find(p => p.商品ID === v.商品ID) || {};
      const warehouseData = tables[warehouseTableIndex]?.records?.find(w => w.倉庫ID === v.倉庫ID) || {};

      // 日付フィルタ（実際の実装では棚卸実施テーブルと結合が必要）
      if (inventoryDate && !v.作成日時?.includes(inventoryDate)) return false;

      // 倉庫フィルタ
      if (warehouse && warehouseData.倉庫コード !== warehouse) return false;

      // カテゴリフィルタ
      if (category && product.カテゴリ !== category) return false;

      // 金額フィルタ
      const diffAmount = Math.abs((v.差異数量 || 0) * (product.標準価格 || 0));
      if (diffAmount < amountMin || diffAmount > amountMax) return false;

      // 差異率フィルタ
      const diffRate = v.帳簿在庫数 > 0 ? (v.差異数量 || 0) / v.帳簿在庫数 * 100 : 0;
      if (diffRate < rateMin || diffRate > rateMax) return false;

      return true;
    });

    renderVariances(filtered);
    drawCauseChart(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['商品名', '倉庫名', '帳簿在庫数', '実地在庫数', '差異数量', '差異金額', '差異原因'];
    const rows = allVariances.map(v => {
      const product = tables[productTableIndex]?.records?.find(p => p.商品ID === v.商品ID) || {};
      const warehouse = tables[warehouseTableIndex]?.records?.find(w => w.倉庫ID === v.倉庫ID) || {};
      const diffAmount = (v.差異数量 || 0) * (product.標準価格 || 0);

      return [
        product.商品名 || '',
        warehouse.倉庫名 || '',
        v.帳簿在庫数 || 0,
        v.実地在庫数 || 0,
        v.差異数量 || 0,
        diffAmount,
        v.差異原因 || ''
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `棚卸差異分析_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  if (varianceTableIndex >= 0) {
    window.aivicApi.list(varianceTableIndex).then(rows => {
      if (rows) {
        allVariances = rows;
        renderVariances(rows);
        drawCauseChart(rows);
      }
    });
  } else {
    // テーブルが見つからない場合は初期データを使用
    allVariances = tables[0]?.records || [];
    renderVariances(allVariances);
    drawCauseChart(allVariances);
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', performSearch);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 詳細ボタンのイベントデリゲーション
  container.addEventListener('click', e => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      // 棚卸実績入力画面に遷移
      window.showScreen('scr-1780995505965');
    }
  });
}

function(container, apiUrl, tables) {
  let selectedProduct = null;
  let currentInventory = null;

  // 商品一覧の再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.id}" class="product-row" style="cursor: pointer; border-bottom: 1px solid rgba(139, 69, 19, 0.1);">
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text);">${product.商品コード || ''}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text);">${product.商品名 || ''}</td>
        <td style="padding: 8px 12px; font-size: 13px; color: var(--text-muted);">${product.カテゴリ || ''}</td>
        <td style="padding: 8px 12px; text-align: center;">
          <button class="action-btn secondary select-product-btn" data-id="${product.id}" style="padding: 4px 8px; font-size: 12px;">選択</button>
        </td>
      </tr>
    `).join('');
  }

  // 在庫情報の取得と表示
  async function loadInventoryInfo(productId, warehouseId) {
    if (!productId || !warehouseId) return;

    try {
      const inventories = await window.aivicApi.list(3); // 在庫テーブル
      const inventory = inventories.find(inv => 
        inv.商品ID === productId && inv.倉庫ID === warehouseId
      );

      currentInventory = inventory;
      const currentStock = inventory ? inventory.現在庫数 : 0;
      container.querySelector('#current-stock').textContent = `${currentStock} ${selectedProduct?.単位 || '個'}`;

      // 更新後在庫数の入力値をクリア
      container.querySelector('#new-stock').value = '';
      container.querySelector('#diff-quantity').textContent = '-';

      // 更新ボタンの有効化チェック
      checkFormValidity();
    } catch (error) {
      console.error('在庫情報の取得に失敗:', error);
      container.querySelector('#current-stock').textContent = '取得エラー';
    }
  }

  // 増減数量の計算と表示
  function updateDiffQuantity() {
    const newStockInput = container.querySelector('#new-stock');
    const diffElement = container.querySelector('#diff-quantity');

    if (!newStockInput.value || !currentInventory) {
      diffElement.textContent = '-';
      return;
    }

    const currentStock = currentInventory.現在庫数 || 0;
    const newStock = parseInt(newStockInput.value);
    const diff = newStock - currentStock;

    diffElement.textContent = diff >= 0 ? `+${diff}` : `${diff}`;
    diffElement.style.color = diff >= 0 ? '#22c55e' : '#ef4444';
  }

  // フォームの有効性チェック
  function checkFormValidity() {
    const updateBtn = container.querySelector('#btn-update-stock');
    const warehouseSelect = container.querySelector('#warehouse-select');
    const newStockInput = container.querySelector('#new-stock');
    const reasonSelect = container.querySelector('#reason-select');

    const isValid = selectedProduct && 
                   warehouseSelect.value && 
                   newStockInput.value !== '' && 
                   reasonSelect.value;

    updateBtn.disabled = !isValid;
  }

  // 商品選択の処理
  function selectProduct(productId) {
    const products = tables[1].records; // 商品マスタ
    selectedProduct = products.find(p => p.id === productId);

    if (selectedProduct) {
      // 選択商品情報の表示
      const infoPanel = container.querySelector('#selected-product-info');
      container.querySelector('#selected-product-code').textContent = selectedProduct.商品コード || '';
      container.querySelector('#selected-product-name').textContent = selectedProduct.商品名 || '';
      container.querySelector('#selected-product-unit').textContent = selectedProduct.単位 || '個';
      container.querySelector('#selected-product-safety').textContent = selectedProduct.安全在庫数 || '0';
      infoPanel.style.display = 'block';

      // 倉庫が選択されていれば在庫情報を取得
      const warehouseSelect = container.querySelector('#warehouse-select');
      if (warehouseSelect.value) {
        loadInventoryInfo(productId, warehouseSelect.value);
      }

      checkFormValidity();
    }
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      const products = await window.aivicApi.list(1); // 商品マスタ
      renderProducts(products || tables[1].records);
    } catch (error) {
      console.error('商品データの取得に失敗:', error);
      renderProducts(tables[1].records || []);
    }
  }

  // 商品検索
  container.querySelector('#btn-search-product').addEventListener('click', async () => {
    const keyword = container.querySelector('#product-search').value.trim();
    try {
      const products = await window.aivicApi.list(1);
      const filtered = keyword ? 
        products.filter(p => 
          (p.商品名 && p.商品名.includes(keyword)) || 
          (p.商品コード && p.商品コード.includes(keyword))
        ) : products;
      renderProducts(filtered);
    } catch (error) {
      console.error('商品検索に失敗:', error);
    }
  });

  // 商品選択のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const selectBtn = e.target.closest('.select-product-btn');
    if (selectBtn) {
      const productId = selectBtn.dataset.id;
      selectProduct(productId);
    }
  });

  // 倉庫選択の変更
  container.querySelector('#warehouse-select').addEventListener('change', (e) => {
    if (selectedProduct && e.target.value) {
      loadInventoryInfo(selectedProduct.id, e.target.value);
    } else {
      container.querySelector('#current-stock').textContent = '未選択';
      container.querySelector('#diff-quantity').textContent = '-';
    }
    checkFormValidity();
  });

  // 更新後在庫数の入力
  container.querySelector('#new-stock').addEventListener('input', () => {
    updateDiffQuantity();
    checkFormValidity();
  });

  // 更新理由の選択
  container.querySelector('#reason-select').addEventListener('change', checkFormValidity);

  // 在庫更新の実行
  container.querySelector('#inventory-update-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    if (!selectedProduct || !currentInventory) {
      alert('商品と倉庫を選択してください');
      return;
    }

    const warehouseId = container.querySelector('#warehouse-select').value;
    const newStock = parseInt(container.querySelector('#new-stock').value);
    const reason = container.querySelector('#reason-select').value;
    const remarks = container.querySelector('#remarks').value;
    const currentStock = currentInventory.現在庫数 || 0;
    const diffQuantity = newStock - currentStock;

    if (!confirm(`在庫を ${currentStock} から ${newStock} に更新しますか？\n増減: ${diffQuantity >= 0 ? '+' : ''}${diffQuantity}`)) {
      return;
    }

    try {
      // 在庫の更新
      await window.aivicApi.update(3, currentInventory.id, {
        現在庫数: newStock,
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user-id'
      });

      // 入出庫履歴の記録
      await window.aivicApi.save(4, {
        商品ID: selectedProduct.id,
        倉庫ID: warehouseId,
        入出庫区分: '調整',
        数量: diffQuantity,
        処理前在庫数: currentStock,
        処理後在庫数: newStock,
        理由コード: reason,
        備考: remarks,
        処理日時: new Date().toISOString(),
        処理者ID: 'current-user-id'
      });

      // 成功メッセージの表示
      const resultDiv = container.querySelector('#update-result');
      const messageDiv = container.querySelector('#result-message');
      messageDiv.textContent = `在庫更新が完了しました（${selectedProduct.商品名}: ${currentStock} → ${newStock}）`;
      resultDiv.style.display = 'block';
      resultDiv.style.background = 'rgba(34, 197, 94, 0.1)';
      resultDiv.style.border = '1px solid rgba(34, 197, 94, 0.3)';
      messageDiv.style.color = '#22c55e';

      // フォームのリセット
      container.querySelector('#inventory-update-form').reset();
      selectedProduct = null;
      currentInventory = null;
      container.querySelector('#selected-product-info').style.display = 'none';
      container.querySelector('#current-stock').textContent = '未選択';
      container.querySelector('#diff-quantity').textContent = '-';
      container.querySelector('#btn-update-stock').disabled = true;

      // 3秒後に結果メッセージを非表示
      setTimeout(() => {
        resultDiv.style.display = 'none';
      }, 3000);

    } catch (error) {
      console.error('在庫更新に失敗:', error);

      // エラーメッセージの表示
      const resultDiv = container.querySelector('#update-result');
      const messageDiv = container.querySelector('#result-message');
      messageDiv.textContent = '在庫更新に失敗しました。再度お試しください。';
      resultDiv.style.display = 'block';
      resultDiv.style.background = 'rgba(239, 68, 68, 0.1)';
      resultDiv.style.border = '1px solid rgba(239, 68, 68, 0.3)';
      messageDiv.style.color = '#ef4444';
    }
  });

  // キャンセルボタン
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    if (confirm('入力内容を破棄して戻りますか？')) {
      window.showScreen('scr-1780995614537'); // 在庫照会画面
    }
  });

  // 初期データの読み込み
  loadInitialData();
}

