        container.querySelector('#unit-price').value = selectedProduct.標準価格 || '';

        // 安全在庫・発注点表示
        container.querySelector('#safety-stock').textContent = 
          (selectedProduct.安全在庫数 || 0).toLocaleString();
        container.querySelector('#reorder-point').textContent = 
          (selectedProduct.発注点 || 0).toLocaleString();

        updateStockInfo();
      }
    }
  }

  // 在庫情報更新
  function updateStockInfo() {
    const warehouseId = container.querySelector('#warehouse-select').value;
    const quantity = parseInt(container.querySelector('#quantity').value) || 0;
    const transactionType = container.querySelector('input[name="transaction-type"]:checked').value;

    if (selectedProduct && warehouseId && stockTableIndex >= 0) {
      currentStock = tables[stockTableIndex].records.find(s => 
        s.商品ID === selectedProduct.商品ID && s.倉庫ID === warehouseId
      );

      const currentQty = currentStock ? currentStock.現在庫数 : 0;
      container.querySelector('#current-stock').textContent = currentQty.toLocaleString();

      // 入出庫後在庫数計算
      let afterQty = currentQty;
      if (quantity > 0) {
        if (transactionType === '入庫' || transactionType === '調整') {
          afterQty = currentQty + quantity;
        } else if (transactionType === '出庫') {
          afterQty = currentQty - quantity;
        }
      }

      container.querySelector('#after-stock').textContent = afterQty.toLocaleString();

      // 在庫状態判定
      const safetyStock = selectedProduct.安全在庫数 || 0;
      const reorderPoint = selectedProduct.発注点 || 0;
      let status = '正常';
      let statusColor = 'var(--primary)';

      if (afterQty <= 0) {
        status = '欠品';
        statusColor = '#dc2626';
      } else if (afterQty <= safetyStock) {
        status = '要注意';
        statusColor = '#f59e0b';
      } else if (afterQty <= reorderPoint) {
        status = '発注推奨';
        statusColor = '#ff6a00';
      }

      const statusEl = container.querySelector('#stock-status');
      statusEl.textContent = status;
      statusEl.style.background = statusColor;
    }
  }

  // 初期データ読み込み
  if (historyTableIndex >= 0) {
    window.aivicApi.list(historyTableIndex).then(rows => {
      if (rows) {
        renderHistory(rows.sort((a, b) => new Date(b.処理日時) - new Date(a.処理日時)));
      }
    });
  }

  // 商品検索ボタン
  container.querySelector('#btn-product-search').addEventListener('click', () => {
    const keyword = container.querySelector('#product-search').value.trim();
    if (productTableIndex >= 0 && keyword) {
      const products = tables[productTableIndex].records.filter(p => 
        p.商品コード.includes(keyword) || p.商品名.includes(keyword)
      );

      const select = container.querySelector('#product-select');
      select.innerHTML = '<option value="">商品を選択してください</option>' +
        products.map(p => `<option value="${p.商品ID}">${p.商品コード} - ${p.商品名}</option>`).join('');
    }
  });

  // 商品選択変更
  container.querySelector('#product-select').addEventListener('change', (e) => {
    if (e.target.value) {
      onProductSelect(e.target.value);
    } else {
      selectedProduct = null;
      container.querySelector('#selected-product').textContent = '商品が選択されていません';
      container.querySelector('#current-stock').textContent = '-';
      container.querySelector('#after-stock').textContent = '-';
      container.querySelector('#stock-unit').textContent = '-';
    }
  });

  // 倉庫・数量・区分変更時の在庫情報更新
  ['#warehouse-select', '#quantity'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', updateStockInfo);
  });

  container.querySelectorAll('input[name="transaction-type"]').forEach(radio => {
    radio.addEventListener('change', updateStockInfo);
  });

  // 登録ボタン
  container.querySelector('#btn-register').addEventListener('click', async (e) => {
    e.preventDefault();

    const transactionType = container.querySelector('input[name="transaction-type"]:checked').value;
    const productId = container.querySelector('#product-select').value;
    const warehouseId = container.querySelector('#warehouse-select').value;
    const quantity = parseInt(container.querySelector('#quantity').value);
    const unitPrice = parseFloat(container.querySelector('#unit-price').value);
    const transactionDate = container.querySelector('#transaction-date').value;
    const remarks = container.querySelector('#remarks').value;

    if (!productId || !warehouseId || !quantity || quantity <= 0) {
      alert('必須項目を入力してください');
      return;
    }

    if (historyTableIndex >= 0) {
      const currentQty = currentStock ? currentStock.現在庫数 : 0;
      let afterQty = currentQty;
      let adjustedQuantity = quantity;

      if (transactionType === '出庫') {
        if (quantity > currentQty) {
          alert('出庫数量が在庫数を超えています');
          return;
        }
        adjustedQuantity = -quantity;
        afterQty = currentQty - quantity;
      } else {
        afterQty = currentQty + quantity;
      }

      const historyData = {
        商品ID: productId,
        倉庫ID: warehouseId,
        入出庫区分: transactionType,
        数量: adjustedQuantity,
        処理前在庫数: currentQty,
        処理後在庫数: afterQty,
        理由コード: transactionType === '入庫' ? '仕入' : transactionType === '出庫' ? '販売' : '調整',
        備考: remarks,
        処理日時: new Date(transactionDate).toISOString(),
        処理者ID: 'current-user-id'
      };

      const saved = await window.aivicApi.save(historyTableIndex, historyData);
      if (saved) {
        // 在庫テーブル更新
        if (stockTableIndex >= 0) {
          if (currentStock) {
            await window.aivicApi.update(stockTableIndex, currentStock.在庫ID, {
              現在庫数: afterQty,
              最終入庫日: transactionType === '入庫' ? new Date().toISOString() : currentStock.最終入庫日,
              最終出庫日: transactionType === '出庫' ? new Date().toISOString() : currentStock.最終出庫日
            });
          } else {
            await window.aivicApi.save(stockTableIndex, {
              商品ID: productId,
              倉庫ID: warehouseId,
              現在庫数: afterQty,
              引当済数量: 0,
              在庫状態: '正常',
              最終入庫日: transactionType === '入庫' ? new Date().toISOString() : null,
              最終出庫日: transactionType === '出庫' ? new Date().toISOString() : null
            });
          }
        }

        alert('入出庫を登録しました');

        // 履歴再読み込み
        window.aivicApi.list(historyTableIndex).then(rows => {
          if (rows) {
            renderHistory(rows.sort((a, b) => new Date(b.処理日時) - new Date(a.処理日時)));
          }
        });

        // 在庫情報更新
        updateStockInfo();

        // フォームクリア
        container.querySelector('#quantity').value = '';
        container.querySelector('#remarks').value = '';
      }
    }
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#stock-form').reset();
    container.querySelector('#selected-product').textContent = '商品が選択されていません';
    container.querySelector('#current-stock').textContent = '-';
    container.querySelector('#after-stock').textContent = '-';
    container.querySelector('#stock-unit').textContent = '-';
    container.querySelector('#safety-stock').textContent = '-';
    container.querySelector('#reorder-point').textContent = '-';
    selectedProduct = null;
    currentStock = null;

    // 現在時刻を再設定
    const now = new Date();
    now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
    container.querySelector('#transaction-date').value = now.toISOString().slice(0, 16);
  });
}

function(container, apiUrl, tables) {
  let isProcessing = false;
  let currentProgress = 0;

  // DOM要素の取得
  const btnStart = container.querySelector('#btn-start');
  const btnCancel = container.querySelector('#btn-cancel');
  const btnBackup = container.querySelector('#btn-backup');
  const btnPreview = container.querySelector('#btn-preview');
  const btnErrors = container.querySelector('#btn-errors');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const progressPercent = container.querySelector('#progress-percent');
  const currentTask = container.querySelector('#current-task');
  const processedCount = container.querySelector('#processed-count');
  const successCount = container.querySelector('#success-count');
  const errorCount = container.querySelector('#error-count');
  const warningCount = container.querySelector('#warning-count');
  const errorModal = container.querySelector('#error-modal');
  const closeErrorModal = container.querySelector('#close-error-modal');
  const errorLogContent = container.querySelector('#error-log-content');

  // 統合処理のシミュレーション
  function simulateIntegration() {
    const tasks = [
      { name: '商品マスタデータ読み込み中...', duration: 1000 },
      { name: '在庫データ読み込み中...', duration: 1500 },
      { name: '入出庫履歴データ読み込み中...', duration: 1200 },
      { name: 'データ整合性チェック実行中...', duration: 2000 },
      { name: '差異データ抽出中...', duration: 800 },
      { name: '統合処理実行中...', duration: 1500 },
      { name: '結果データ保存中...', duration: 1000 }
    ];

    let taskIndex = 0;
    const totalDuration = tasks.reduce((sum, task) => sum + task.duration, 0);
    let elapsedTime = 0;

    function executeTask() {
      if (taskIndex >= tasks.length || !isProcessing) {
        // 処理完了
        completeIntegration();
        return;
      }

      const task = tasks[taskIndex];
      currentTask.textContent = task.name;

      const taskProgress = setInterval(() => {
        if (!isProcessing) {
          clearInterval(taskProgress);
          return;
        }

        elapsedTime += 100;
        currentProgress = Math.min((elapsedTime / totalDuration) * 100, 100);

        progressBar.style.width = currentProgress + '%';
        progressPercent.textContent = Math.round(currentProgress) + '%';

        if (elapsedTime >= tasks.slice(0, taskIndex + 1).reduce((sum, t) => sum + t.duration, 0)) {
          clearInterval(taskProgress);
          taskIndex++;
          executeTask();
        }
      }, 100);
    }

    executeTask();
  }

  function completeIntegration() {
    isProcessing = false;
    progressText.textContent = '処理完了';
    currentTask.textContent = 'データ統合処理が正常に完了しました';
    btnStart.style.display = 'block';
    btnCancel.style.display = 'none';

    // 結果サマリーの更新
    processedCount.textContent = '1,247';
    successCount.textContent = '1,244';
    errorCount.textContent = '0';
    warningCount.textContent = '3';

    // 通知設定チェック
    const notificationEnabled = container.querySelector('#notification-enabled').checked;
    if (notificationEnabled) {
      // 実際のアプリでは通知APIを使用
      alert('データ統合処理が完了しました');
    }
  }

  // 統合処理開始
  btnStart.addEventListener('click', async () => {
    // 選択されたデータソースをチェック
    const selectedSources = [];
    container.querySelectorAll('input[type="checkbox"]:checked').forEach(cb => {
      if (cb.dataset.testid && cb.dataset.testid.startsWith('source-')) {
        selectedSources.push(cb.dataset.testid.replace('source-', ''));
      }
    });

    if (selectedSources.length === 0) {
      alert('統合対象のデータソースを選択してください');
      return;
    }

    const integrationMode = container.querySelector('#integration-mode').value;
    if (!integrationMode) {
      alert('統合モードを選択してください');
      return;
    }

    isProcessing = true;
    currentProgress = 0;

    btnStart.style.display = 'none';
    btnCancel.style.display = 'block';
    progressText.textContent = '処理中';
    progressBar.style.width = '0%';
    progressPercent.textContent = '0%';

    // 結果サマリーをリセット
    processedCount.textContent = '-';
    successCount.textContent = '-';
    errorCount.textContent = '-';
    warningCount.textContent = '-';

    simulateIntegration();
  });

  // 処理キャンセル
  btnCancel.addEventListener('click', () => {
    if (confirm('統合処理をキャンセルしますか？')) {
      isProcessing = false;
      progressText.textContent = 'キャンセル済み';
      currentTask.textContent = '処理がキャンセルされました';
      btnStart.style.display = 'block';
      btnCancel.style.display = 'none';
    }
  });

  // バックアップ作成
  btnBackup.addEventListener('click', async () => {
    try {
      // 全テーブルのデータを取得してバックアップ
      const backupData = {};
      for (let i = 0; i < tables.length; i++) {
        const data = await window.aivicApi.list(i);
        if (data) {
          backupData[tables[i].tableName] = data;
        }
      }

      // JSONファイルとしてダウンロード
      const blob = new Blob([JSON.stringify(backupData, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `inventory_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      alert('バックアップファイルをダウンロードしました');
    } catch (error) {
      alert('バックアップ作成に失敗しました');
    }
  });

  // エラーログ表示
  btnErrors.addEventListener('click', () => {
    errorLogContent.textContent = `[2024-01-15 10:30:15] INFO: データ統合処理を開始しました
[2024-01-15 10:30:16] INFO: 商品マスタデータ読み込み完了 (1,247件)
[2024-01-15 10:30:18] INFO: 在庫データ読み込み完了 (3,421件)
[2024-01-15 10:30:20] WARN: 商品ID "PRD-001" の在庫数に軽微な差異を検出
[2024-01-15 10:30:20] WARN: 商品ID "PRD-045" の在庫数に軽微な差異を検出
[2024-01-15 10:30:20] WARN: 商品ID "PRD-123" の在庫数に軽微な差異を検出
[2024-01-15 10:30:22] INFO: 入出庫履歴データ読み込み完了 (8,765件)
[2024-01-15 10:30:25] INFO: データ整合性チェック完了
[2024-01-15 10:30:26] INFO: 統合処理完了 (成功: 1,244件, 警告: 3件)`;
    errorModal.style.display = 'block';
  });

  // エラーモーダルを閉じる
  closeErrorModal.addEventListener('click', () => {
    errorModal.style.display = 'none';
  });

  // モーダル外クリックで閉じる
  errorModal.addEventListener('click', (e) => {
    if (e.target === errorModal) {
      errorModal.style.display = 'none';
    }
  });

  // 初期データの表示（処理履歴などがあれば表示）
  if (tables && tables.length > 0) {
    // 初期状態では待機中として表示
    progressText.textContent = '待機中';
    currentTask.textContent = '統合処理を開始してください';
  }
}

function(container, apiUrl, tables) {
  // 今日の日付をデフォルトで設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#inventory-date').value = today;

  // プレビューボタンのイベントリスナー
  container.querySelector('#btn-preview').addEventListener('click', async () => {
    const warehouseId = container.querySelector('#warehouse-select').value;
    const inventoryDate = container.querySelector('#inventory-date').value;
    const productCodeFrom = container.querySelector('#product-code-from').value;
    const productCodeTo = container.querySelector('#product-code-to').value;
    const selectedCategories = Array.from(container.querySelectorAll('.checkbox-item input:checked')).map(cb => cb.value);
    const sortOrder = container.querySelector('#sort-order').value;

    if (!warehouseId) {
      alert('倉庫を選択してください');
      return;
    }

    if (!inventoryDate) {
      alert('棚卸実施日を選択してください');
      return;
    }

    try {
      // 商品マスタと在庫データを取得
      const products = await window.aivicApi.list(1) || []; // 商品マスタ
      const inventory = await window.aivicApi.list(3) || []; // 在庫

      // フィルタリング条件を適用
      let filteredData = products.filter(product => {
        // 商品コード範囲チェック
        if (productCodeFrom && product.商品コード < productCodeFrom) return false;
        if (productCodeTo && product.商品コード > productCodeTo) return false;

        // カテゴリチェック
        if (selectedCategories.length > 0 && !selectedCategories.includes(product.カテゴリ)) return false;

        return product.有効フラグ;
      });

      // 在庫情報と結合
      const previewData = filteredData.map(product => {
        const stock = inventory.find(inv => inv.商品ID === product.商品ID && inv.倉庫ID === warehouseId);
        return {
          商品コード: product.商品コード || '',
          商品名: product.商品名 || '',
          カテゴリ: product.カテゴリ || '',
          単位: product.単位 || '',
          理論在庫: stock ? stock.現在庫数 : 0,
          実地在庫: '', // 棚卸時に記入
          備考: ''
        };
      });

      // ソート処理
      previewData.sort((a, b) => {
        switch (sortOrder) {
          case 'product_name':
            return a.商品名.localeCompare(b.商品名);
          case 'category':
            return a.カテゴリ.localeCompare(b.カテゴリ);
          case 'location':
            return a.商品コード.localeCompare(b.商品コード);
          default:
            return a.商品コード.localeCompare(b.商品コード);
        }
      });

      // プレビューテーブルを表示
      renderPreview(previewData);
      container.querySelector('#preview-section').style.display = 'block';

    } catch (error) {
      console.error('プレビュー生成エラー:', error);
      alert('プレビューの生成に失敗しました');
    }
  });

  // プレビュー描画関数
  function renderPreview(data) {
    const tbody = container.querySelector('#preview-tbody');
    tbody.innerHTML = data.slice(0, 20).map(item => `
      <tr>
        <td>${item.商品コード}</td>
        <td>${item.商品名}</td>
        <td>${item.カテゴリ}</td>
        <td>${item.単位}</td>
        <td style="text-align: right;">${item.理論在庫}</td>
        <td style="text-align: right; background: rgba(255,255,255,0.05);">_____</td>
        <td style="background: rgba(255,255,255,0.05);">_____</td>
      </tr>
    `).join('');

    if (data.length > 20) {
      tbody.innerHTML += `<tr><td colspan="7" style="text-align: center; color: var(--text-muted); font-style: italic;">他 ${data.length - 20} 件...</td></tr>`;
    }
  }

  // 出力実行ボタンのイベントリスナー
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const warehouseId = container.querySelector('#warehouse-select').value;
    const inventoryDate = container.querySelector('#inventory-date').value;
    const outputFormat = container.querySelector('input[name="output-format"]:checked').value;

    if (!warehouseId) {
      alert('倉庫を選択してください');
      return;
    }

    if (!inventoryDate) {
      alert('棚卸実施日を選択してください');
      return;
    }

    try {
      // プレビューと同じロジックでデータを取得
      const products = await window.aivicApi.list(1) || [];
      const inventory = await window.aivicApi.list(3) || [];
      const selectedCategories = Array.from(container.querySelectorAll('.checkbox-item input:checked')).map(cb => cb.value);
      const productCodeFrom = container.querySelector('#product-code-from').value;
      const productCodeTo = container.querySelector('#product-code-to').value;
      const sortOrder = container.querySelector('#sort-order').value;

      let filteredData = products.filter(product => {
        if (productCodeFrom && product.商品コード < productCodeFrom) return false;
        if (productCodeTo && product.商品コード > productCodeTo) return false;
        if (selectedCategories.length > 0 && !selectedCategories.includes(product.カテゴリ)) return false;
        return product.有効フラグ;
      });

      const exportData = filteredData.map(product => {
        const stock = inventory.find(inv => inv.商品ID === product.商品ID && inv.倉庫ID === warehouseId);
        return {
          商品コード: product.商品コード || '',
          商品名: product.商品名 || '',
          カテゴリ: product.カテゴリ || '',
          単位: product.単位 || '',
          理論在庫: stock ? stock.現在庫数 : 0,
          実地在庫: '',
          備考: ''
        };
      });

      // ソート処理
      exportData.sort((a, b) => {
        switch (sortOrder) {
          case 'product_name':
            return a.商品名.localeCompare(b.商品名);
          case 'category':
            return a.カテゴリ.localeCompare(b.カテゴリ);
          case 'location':
            return a.商品コード.localeCompare(b.商品コード);
          default:
            return a.商品コード.localeCompare(b.商品コード);
        }
      });

      if (outputFormat === 'Excel') {
        // CSV形式でエクスポート
        const headers = ['商品コード', '商品名', 'カテゴリ', '単位', '理論在庫', '実地在庫', '備考'];
        const csvContent = '\uFEFF' + [
          headers.join(','),
          ...exportData.map(row => headers.map(header => {
            const value = row[header] || '';
            return typeof value === 'string' && value.includes(',') ? `"${value}"` : value;
          }).join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `棚卸リスト_${inventoryDate}_${warehouseId}.csv`;
        link.click();
      } else {
        // PDF出力（実際の実装では専用ライブラリを使用）
        alert(`PDF形式での出力が完了しました。\n対象件数: ${exportData.length}件\n出力日時: ${new Date().toLocaleString()}`);
      }

      // 棚卸実施レコードを作成
      const warehouseName = container.querySelector('#warehouse-select option:checked').textContent;
      await window.aivicApi.save(4, { // 棚卸実施テーブル
        倉庫ID: warehouseId,
        棚卸実施日: new Date(inventoryDate).toISOString(),
        ステータス: '実施中',
        備考: `棚卸リスト出力 - ${warehouseName} - ${exportData.length}件`,
        実施者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
      });

    } catch (error) {
      console.error('出力エラー:', error);
      alert('出力処理に失敗しました');
    }
  });

  // 条件クリアボタンのイベントリスナー
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#warehouse-select').value = '';
    container.querySelector('#inventory-date').value = today;
    container.querySelector('#product-code-from').value = '';
    container.querySelector('#product-code-to').value = '';
    container.querySelector('#sort-order').value = 'product_code';
    container.querySelector('input[name="output-format"][value="PDF"]').checked = true;

    // チェックボックスをすべてクリア
    container.querySelectorAll('.checkbox-item input').forEach(cb => cb.checked = false);

    // プレビューを非表示
    container.querySelector('#preview-section').style.display = 'none';
  });

  // キャンセルボタンのイベントリスナー
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1780995495139'); // 棚卸実施管理画面へ
  });
}

function(container, apiUrl, tables) {
  let selectedVarianceId = null;
  let currentVariances = [];

  // 差異一覧の再描画
  function renderVariances(variances) {
    const tbody = container.querySelector('#variance-tbody');
    const countEl = container.querySelector('#variance-count');

    currentVariances = variances;
    countEl.textContent = variances.length;

    tbody.innerHTML = variances.map(v => {
      const statusBadge = v.調整済フラグ ? 
        '<span class="px-2 py-1 text-xs rounded" style="background: rgba(34, 197, 94, 0.2); color: #22c562;">調整済</span>' :
        '<span class="px-2 py-1 text-xs rounded" style="background: rgba(239, 68, 68, 0.2); color: #ef4444;">未調整</span>';

      return `
        <tr class="hover:bg-opacity-50 cursor-pointer variance-row" data-id="${v.棚卸差異ID}" style="border-bottom: 1px solid var(--border);">
          <td class="p-2" style="color: var(--text);">${v.商品コード || ''}</td>
          <td class="p-2" style="color: var(--text);">${v.商品名 || ''}</td>
          <td class="p-2" style="color: var(--text);">${v.倉庫名 || ''}</td>
          <td class="p-2 text-right" style="color: var(--text);">${v.帳簿在庫数 || 0}</td>
          <td class="p-2 text-right" style="color: var(--text);">${v.実地在庫数 || 0}</td>
          <td class="p-2 text-right" style="color: ${v.差異数量 > 0 ? '#22c562' : v.差異数量 < 0 ? '#ef4444' : 'var(--text)'};">${v.差異数量 > 0 ? '+' : ''}${v.差異数量 || 0}</td>
          <td class="p-2" style="color: var(--text);">${v.差異区分 || ''}</td>
          <td class="p-2">${statusBadge}</td>
        </tr>
      `;
    }).join('');
  }

  // 差異詳細の表示
  function renderVarianceDetail(variance) {
    const detailEl = container.querySelector('#variance-detail');
    if (!variance) {
      detailEl.innerHTML = `
        <div class="text-center py-8" style="color: var(--text-muted);">
          <p class="text-sm">差異を選択してください</p>
        </div>
      `;
      return;
    }

    const diffAmount = (variance.差異数量 || 0) * (variance.単価 || 0);

    detailEl.innerHTML = `
      <div class="space-y-3">
        <div class="border-b pb-2" style="border-color: var(--border);">
          <h3 class="text-sm font-medium mb-1" style="color: var(--text);">${variance.商品名 || ''}</h3>
          <p class="text-xs" style="color: var(--text-muted);">商品コード: ${variance.商品コード || ''}</p>
        </div>

        <div class="grid grid-cols-2 gap-2 text-xs">
          <div>
            <span style="color: var(--text-muted);">帳簿在庫:</span>
            <span style="color: var(--text);">${variance.帳簿在庫数 || 0}</span>
          </div>
          <div>
            <span style="color: var(--text-muted);">実地在庫:</span>
            <span style="color: var(--text);">${variance.実地在庫数 || 0}</span>
          </div>
          <div>
            <span style="color: var(--text-muted);">差異数量:</span>
            <span style="color: ${variance.差異数量 > 0 ? '#22c562' : variance.差異数量 < 0 ? '#ef4444' : 'var(--text)'};">
              ${variance.差異数量 > 0 ? '+' : ''}${variance.差異数量 || 0}
            </span>
          </div>
          <div>
            <span style="color: var(--text-muted);">差異金額:</span>
            <span style="color: ${diffAmount > 0 ? '#22c562' : diffAmount < 0 ? '#ef4444' : 'var(--text)'};">
              ¥${diffAmount.toLocaleString()}
            </span>
          </div>
        </div>

        <div>
          <label class="block text-xs mb-1" style="color: var(--text-muted);">差異原因</label>
          <select data-testid="variance-cause-select" id="variance-cause-select" class="w-full px-2 py-1 text-xs rounded border" style="background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.18); color: var(--text);">
            <option value="">選択してください</option>
            <option value="入力ミス" ${variance.差異原因 === '入力ミス' ? 'selected' : ''}>入力ミス</option>
            <option value="紛失" ${variance.差異原因 === '紛失' ? 'selected' : ''}>紛失</option>
            <option value="盗難" ${variance.差異原因 === '盗難' ? 'selected' : ''}>盗難</option>
            <option value="破損" ${variance.差異原因 === '破損' ? 'selected' : ''}>破損</option>
            <option value="計数ミス" ${variance.差異原因 === '計数ミス' ? 'selected' : ''}>計数ミス</option>
            <option value="システムエラー" ${variance.差異原因 === 'システムエラー' ? 'selected' : ''}>システムエラー</option>
          </select>
        </div>

        <div>
          <label class="block text-xs mb-1" style="color: var(--text-muted);">備考</label>
          <textarea data-testid="variance-notes" id="variance-notes" rows="3" class="w-full px-2 py-1 text-xs rounded border" style="background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.18); color: var(--text);" placeholder="差異の詳細や対応策を入力">${variance.備考 || ''}</textarea>
        </div>

        <div class="space-y-2">
          <button data-testid="update-variance" id="btn-update-variance" class="action-btn w-full py-1 text-xs">差異情報更新</button>
          ${!variance.調整済フラグ ? '<button data-testid="approve-variance" id="btn-approve-variance" class="action-btn w-full py-1 text-xs">差異承認</button>' : ''}
          <button data-testid="view-stocktaking" class="action-btn secondary w-full py-1 text-xs" onclick="window.showScreen('scr-1780995495139')">棚卸管理画面へ</button>
        </div>
      </div>
    `;
  }

  // 初期データ読み込み
  async function loadVariances() {
    const variances = await window.aivicApi.list(5); // 棚卸差異テーブル
    if (variances) {
      // 商品名、倉庫名を結合
      for (let v of variances) {
        const product = tables[1].records.find(p => p.商品ID === v.商品ID);
        const warehouse = tables[2].records.find(w => w.倉庫ID === v.倉庫ID);
        v.商品名 = product?.商品名 || '';
        v.商品コード = product?.商品コード || '';
        v.倉庫名 = warehouse?.倉庫名 || '';
        v.単価 = product?.標準価格 || 0;
      }
      renderVariances(variances);
    }
  }

  // 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const stocktakingId = container.querySelector('#stocktaking-select').value;
    const warehouseId = container.querySelector('#warehouse-select').value;
    const category = container.querySelector('#category-select').value;
    const varianceType = container.querySelector('#variance-type-select').value;
    const minAmount = parseInt(container.querySelector('#min-amount-input').value) || 0;
    const maxAmount = parseInt(container.querySelector('#max-amount-input').value) || 999999999;

    let variances = await window.aivicApi.list(5);
    if (!variances) return;

    // 商品名、倉庫名を結合
    for (let v of variances) {
      const product = tables[1].records.find(p => p.商品ID === v.商品ID);
      const warehouse = tables[2].records.find(w => w.倉庫ID === v.倉庫ID);
      v.商品名 = product?.商品名 || '';
      v.商品コード = product?.商品コード || '';
      v.倉庫名 = warehouse?.倉庫名 || '';
      v.単価 = product?.標準価格 || 0;
      v.カテゴリ = product?.カテゴリ || '';
    }

    // フィルタリング
    variances = variances.filter(v => {
      if (warehouseId && v.倉庫ID !== warehouseId) return false;
      if (category && v.カテゴリ !== category) return false;
      if (varianceType && v.差異区分 !== varianceType) return false;

      const diffAmount = Math.abs((v.差異数量 || 0) * (v.単価 || 0));
      if (diffAmount < minAmount || diffAmount > maxAmount) return false;

      return true;
    });

    renderVariances(variances);
  });

  // 差異行クリック
  container.addEventListener('click', (e) => {
    const row = e.target.closest('.variance-row');
    if (row) {
      selectedVarianceId = row.dataset.id;
      const variance = currentVariances.find(v => v.棚卸差異ID === selectedVarianceId);
      renderVarianceDetail(variance);

      // 選択状態の表示
      container.querySelectorAll('.variance-row').forEach(r => r.style.backgroundColor = '');
      row.style.backgroundColor = 'rgba(var(--primary-rgb), 0.1)';
    }
  });

  // 差異情報更新
  container.addEventListener('click', async (e) => {
    if (e.target.id === 'btn-update-variance' && selectedVarianceId) {
      const cause = container.querySelector('#variance-cause-select').value;
      const notes = container.querySelector('#variance-notes').value;

      const updated = await window.aivicApi.update(5, selectedVarianceId, {
        差異原因: cause,
        備考: notes
      });

      if (updated) {
        loadVariances();
        const variance = currentVariances.find(v => v.棚卸差異ID === selectedVarianceId);
        if (variance) {
          variance.差異原因 = cause;
          variance.備考 = notes;
          renderVarianceDetail(variance);
        }
      }
    }
  });

  // 差異承認モーダル
  container.addEventListener('click', (e) => {
    if (e.target.id === 'btn-approve-variance') {
      container.querySelector('#approval-modal').style.display = 'flex';
    }
  });

  container.querySelector('#btn-cancel-approval').addEventListener('click', () => {
    container.querySelector('#approval-modal').style.display = 'none';
  });

  container.querySelector('#btn-confirm-approval').addEventListener('click', async () => {
    if (!selectedVarianceId) return;

    const comment = container.querySelector('#approval-comment').value;
    const updated = await window.aivicApi.update(5, selectedVarianceId, {
      調整済フラグ: true,
      備考: comment
    });

    if (updated) {
      container.querySelector('#approval-modal').style.display = 'none';
      loadVariances();
      const variance = currentVariances.find(v => v.棚卸差異ID === selectedVarianceId);
      if (variance) {
        variance.調整済フラグ = true;
        variance.備考 = comment;
        renderVarianceDetail(variance);
      }
    }
  });

  // 初期読み込み
  loadVariances();
}

