      品質評価: ''
    }
  ];

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    if (!tbody) return;

    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(r => `
      <tr data-id="${r.id}" class="border-b hover:bg-opacity-50" style="border-color: var(--border);">
        <td class="px-3 py-2 text-sm" style="color: var(--text);">${r.製造日 || ''}</td>
        <td class="px-3 py-2 text-sm" style="color: var(--text);">${r.製品名 || ''}</td>
        <td class="px-3 py-2 text-sm" style="color: var(--text);">${r.ロット番号 || ''}</td>
        <td class="px-3 py-2 text-sm" style="color: var(--text);">${r.製造ライン || ''}</td>
        <td class="px-3 py-2 text-sm" style="color: var(--text);">${r.工程 || ''}</td>
        <td class="px-3 py-2 text-sm" style="color: var(--text);">${r.数量 || ''}</td>
        <td class="px-3 py-2 text-sm" style="color: var(--text);">${r.作業者 || ''}</td>
        <td class="px-3 py-2 text-sm" style="color: var(--text);">
          <span class="px-2 py-1 rounded text-xs" style="background: ${getStatusColor(r.ステータス)}; color: #fff;">
            ${r.ステータス || ''}
          </span>
        </td>
        <td class="px-3 py-2 text-sm">
          <button class="action-btn secondary detail-btn px-2 py-1 text-xs mr-1" data-id="${r.id}" 
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); border-radius: 3px;">
            詳細
          </button>
        </td>
      </tr>
    `).join('');

    // レコード数とページ情報を更新
    const recordCount = container.querySelector('#record-count');
    const pageInfo = container.querySelector('#page-info');
    if (recordCount) recordCount.textContent = rows.length;

    const totalPages = Math.ceil(rows.length / itemsPerPage);
    if (pageInfo) pageInfo.textContent = `${currentPage} / ${totalPages}`;

    // ページネーションボタンの状態更新
    const prevBtn = container.querySelector('#btn-prev');
    const nextBtn = container.querySelector('#btn-next');
    if (prevBtn) prevBtn.disabled = currentPage <= 1;
    if (nextBtn) nextBtn.disabled = currentPage >= totalPages;
  }

  function getStatusColor(status) {
    switch(status) {
      case '完了': return '#22c55e';
      case '進行中': return '#3b82f6';
      case '待機': return '#f59e0b';
      default: return '#6b7280';
    }
  }

  // 2. 初期データを即座に描画
  allRecords = tables[0]?.records || sampleData;
  filteredRecords = [...allRecords];
  renderRows(filteredRecords);

  // 3. 検索ボタンのイベントリスナー
  const searchBtn = container.querySelector('#btn-search');
  if (searchBtn) {
    searchBtn.addEventListener('click', () => {
      const productName = container.querySelector('#product-name-search')?.value || '';
      const startDate = container.querySelector('#start-date')?.value || '';
      const endDate = container.querySelector('#end-date')?.value || '';
      const manufacturingLine = container.querySelector('#manufacturing-line')?.value || '';
      const lotNumber = container.querySelector('#lot-number')?.value || '';
      const processFilter = container.querySelector('#process-filter')?.value || '';

      filteredRecords = allRecords.filter(record => {
        let match = true;

        if (productName && !record.製品名?.includes(productName)) match = false;
        if (startDate && record.製造日 < startDate) match = false;
        if (endDate && record.製造日 > endDate) match = false;
        if (manufacturingLine && record.製造ライン !== manufacturingLine) match = false;
        if (lotNumber && !record.ロット番号?.includes(lotNumber)) match = false;
        if (processFilter && record.工程 !== processFilter) match = false;

        return match;
      });

      currentPage = 1;
      renderRows(filteredRecords);
    });
  }

  // 条件クリアボタン
  const clearBtn = container.querySelector('#btn-clear');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      container.querySelector('#product-name-search').value = '';
      container.querySelector('#start-date').value = '';
      container.querySelector('#end-date').value = '';
      container.querySelector('#manufacturing-line').value = '';
      container.querySelector('#lot-number').value = '';
      container.querySelector('#process-filter').value = '';

      filteredRecords = [...allRecords];
      currentPage = 1;
      renderRows(filteredRecords);
    });
  }

  // CSVエクスポートボタン
  const csvExportBtn = container.querySelector('#btn-csv-export');
  if (csvExportBtn) {
    csvExportBtn.addEventListener('click', () => {
      const headers = ['製造日', '製品名', 'ロット番号', '製造ライン', '工程', '数量', '作業者', 'ステータス'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...filteredRecords.map(record => 
          headers.map(header => `"${record[header] || ''}"`).join(',')
        )
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `製造履歴_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    });
  }

  // ページネーション
  const prevBtn = container.querySelector('#btn-prev');
  const nextBtn = container.querySelector('#btn-next');

  if (prevBtn) {
    prevBtn.addEventListener('click', () => {
      if (currentPage > 1) {
        currentPage--;
        renderRows(filteredRecords);
      }
    });
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', () => {
      const totalPages = Math.ceil(filteredRecords.length / itemsPerPage);
      if (currentPage < totalPages) {
        currentPage++;
        renderRows(filteredRecords);
      }
    });
  }

  // 詳細表示モーダル
  const detailModal = container.querySelector('#detail-modal');
  const closeDetailBtn = container.querySelector('#btn-close-detail');

  if (closeDetailBtn) {
    closeDetailBtn.addEventListener('click', () => {
      detailModal.style.display = 'none';
    });
  }

  // 在庫照会へ遷移
  const gotoInventoryBtn = container.querySelector('#btn-goto-inventory');
  if (gotoInventoryBtn) {
    gotoInventoryBtn.addEventListener('click', () => {
      window.showScreen('scr-1780995614537'); // 在庫照会画面
    });
  }

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');

    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      const record = filteredRecords.find(r => r.id === recordId);

