            <div class="text-sm" style="color: var(--text);">${record.品質評価 || ''}</div>
          </div>
        `;

        detailModal.style.display = 'flex';
      }
    }
  });

  // モーダル背景クリックで閉じる
  if (detailModal) {
    detailModal.addEventListener('click', (e) => {
      if (e.target === detailModal) {
        detailModal.style.display = 'none';
      }
    });
  }
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#difference-tbody');
  const selectAllCheckbox = container.querySelector('#select-all');

  // 差異データを結合して表示用データを作成
  function createDifferenceData() {
    const stocktakingResults = tables.find(t => t.tableName === '棚卸実績')?.records || [];
    const differences = tables.find(t => t.tableName === '棚卸差異')?.records || [];
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const warehouses = tables.find(t => t.tableName === '倉庫マスタ')?.records || [];

    return differences.map(diff => {
      const product = products.find(p => p.商品ID === diff.商品ID) || {};
      const warehouse = warehouses.find(w => w.倉庫ID === diff.倉庫ID) || {};
      const result = stocktakingResults.find(r => r.棚卸実績ID === diff.棚卸実績ID) || {};

      return {
        id: diff.棚卸差異ID,
        商品コード: product.商品コード || '',
        商品名: product.商品名 || '',
        倉庫名: warehouse.倉庫名 || '',
        理論在庫数: diff.帳簿在庫数 || 0,
        実地在庫数: diff.実地在庫数 || 0,
        差異数量: diff.差異数量 || 0,
        差異区分: diff.差異区分 || '',
        差異原因: diff.差異原因 || '',
        調整済フラグ: diff.調整済フラグ || false,
        備考: diff.備考 || ''
      };
    });
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" style="${row.調整済フラグ ? 'opacity: 0.6;' : ''}">
        <td style="text-align: center;">
          <input type="checkbox" class="row-checkbox" data-id="${row.id}" ${row.調整済フラグ ? 'disabled' : ''} style="accent-color: var(--primary);">
        </td>
        <td style="font-family: monospace;">${row.商品コード}</td>
        <td>${row.商品名}</td>
        <td>${row.倉庫名}</td>
        <td style="text-align: right; font-family: monospace;">${row.理論在庫数.toLocaleString()}</td>
        <td style="text-align: right; font-family: monospace;">${row.実地在庫数.toLocaleString()}</td>
        <td style="text-align: right; font-family: monospace; color: ${row.差異数量 > 0 ? '#22c55e' : row.差異数量 < 0 ? '#ef4444' : 'var(--text)'};">
          ${row.差異数量 > 0 ? '+' : ''}${row.差異数量.toLocaleString()}
        </td>
        <td>
          <select class="reason-select" data-id="${row.id}" ${row.調整済フラグ ? 'disabled' : ''} style="width: 100%; padding: 4px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
            <option value="">選択</option>
            <option value="counting-error" ${row.差異原因 === 'counting-error' ? 'selected' : ''}>カウントミス</option>
            <option value="system-error" ${row.差異原因 === 'system-error' ? 'selected' : ''}>入力ミス</option>
            <option value="damage" ${row.差異原因 === 'damage' ? 'selected' : ''}>破損</option>
            <option value="theft" ${row.差異原因 === 'theft' ? 'selected' : ''}>紛失</option>
            <option value="other" ${row.差異原因 === 'other' ? 'selected' : ''}>その他</option>
          </select>
        </td>
        <td>
          <input type="text" class="adjustment-input" data-id="${row.id}" value="${row.備考}" ${row.調整済フラグ ? 'disabled' : ''} placeholder="調整理由" style="width: 100%; padding: 4px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
        </td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 500; ${row.調整済フラグ ? 'background: #22c55e; color: #fff;' : 'background: rgba(255,165,0,0.2); color: #ffa500; border: 1px solid #ffa500;'}">
            ${row.調整済フラグ ? '確定済' : '未確定'}
          </span>
        </td>
        <td>
          ${!row.調整済フラグ ? `<button class="action-btn secondary confirm-btn" data-id="${row.id}" style="padding: 4px 8px; font-size: 12px;">確定</button>` : ''}
        </td>
      </tr>
    `).join('');

    updateSelectAllState();
  }

  // 全選択チェックボックスの状態更新
  function updateSelectAllState() {
    const checkboxes = container.querySelectorAll('.row-checkbox:not([disabled])');
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');

    if (checkboxes.length === 0) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
    } else if (checkedBoxes.length === checkboxes.length) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = true;
    } else if (checkedBoxes.length > 0) {
      selectAllCheckbox.indeterminate = true;
      selectAllCheckbox.checked = false;
    } else {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
    }
  }

  // 初期データ表示
  let currentData = createDifferenceData();
  renderRows(currentData);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', () => {
    const stocktakingId = container.querySelector('#stocktaking-select').value;
    const warehouseId = container.querySelector('#warehouse-select').value;
    const productSearch = container.querySelector('#product-search').value.toLowerCase();

    let filteredData = createDifferenceData();

    if (stocktakingId) {
      // 実際の実装では棚卸実施IDでフィルタリング
      filteredData = filteredData.filter(row => true); // プレースホルダー
    }

    if (warehouseId) {
      filteredData = filteredData.filter(row => row.倉庫名.includes(warehouseId));
    }

    if (productSearch) {
      filteredData = filteredData.filter(row => 
        row.商品コード.toLowerCase().includes(productSearch) ||
        row.商品名.toLowerCase().includes(productSearch)
      );
    }

    renderRows(filteredData);
  });

  // 全選択チェックボックス
  selectAllCheckbox.addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox:not([disabled])');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('row-checkbox')) {
      updateSelectAllState();
    }
  });

  // 選択項目確定
  container.querySelector('#btn-confirm-selected').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('確定する項目を選択してください。');
      return;
    }

    if (!confirm(`選択した${checkedBoxes.length}件の差異を確定しますか？`)) {
      return;
    }

    const differenceTableIndex = tables.findIndex(t => t.tableName === '棚卸差異');

    for (const checkbox of checkedBoxes) {
      const id = checkbox.dataset.id;
      const reasonSelect = container.querySelector(`.reason-select[data-id="${id}"]`);
      const adjustmentInput = container.querySelector(`.adjustment-input[data-id="${id}"]`);

      await window.aivicApi.update(differenceTableIndex, id, {
        調整済フラグ: true,
        差異原因: reasonSelect.value,
        備考: adjustmentInput.value,
        更新日時: new Date().toISOString()
      });
    }

    // データ再読み込み
    const updatedDifferences = await window.aivicApi.list(differenceTableIndex);
    if (updatedDifferences) {
      tables[differenceTableIndex].records = updatedDifferences;
      currentData = createDifferenceData();
      renderRows(currentData);
    }
  });

  // 一括確定
  container.querySelector('#btn-bulk-confirm').addEventListener('click', async () => {
    const reasonSelect = container.querySelector('#reason-select');
    const adjustmentReason = container.querySelector('#adjustment-reason');

    if (!reasonSelect.value) {
      alert('差異理由を選択してください。');
      return;
    }

    const uncheckedBoxes = container.querySelectorAll('.row-checkbox:not([disabled]):not(:checked)');
    if (uncheckedBoxes.length === 0) {
      alert('確定する項目がありません。');
      return;
    }

    if (!confirm('未確定の全ての差異を一括確定しますか？')) {
      return;
    }

    const differenceTableIndex = tables.findIndex(t => t.tableName === '棚卸差異');

    for (const checkbox of container.querySelectorAll('.row-checkbox:not([disabled])')) {
      const id = checkbox.dataset.id;

      await window.aivicApi.update(differenceTableIndex, id, {
        調整済フラグ: true,
        差異原因: reasonSelect.value,
        備考: adjustmentReason.value,
        更新日時: new Date().toISOString()
      });
    }

    // データ再読み込み
    const updatedDifferences = await window.aivicApi.list(differenceTableIndex);
    if (updatedDifferences) {
      tables[differenceTableIndex].records = updatedDifferences;
      currentData = createDifferenceData();
      renderRows(currentData);
    }

    // フォームリセット
    reasonSelect.value = '';
    adjustmentReason.value = '';
  });

  // 個別確定ボタン
  container.addEventListener('click', async (e) => {
    const confirmBtn = e.target.closest('.confirm-btn');
    if (confirmBtn) {
      const id = confirmBtn.dataset.id;
      const reasonSelect = container.querySelector(`.reason-select[data-id="${id}"]`);
      const adjustmentInput = container.querySelector(`.adjustment-input[data-id="${id}"]`);

      if (!reasonSelect.value) {
        alert('差異理由を選択してください。');
        return;
      }

      if (!confirm('この差異を確定しますか？')) {
        return;
      }

      const differenceTableIndex = tables.findIndex(t => t.tableName === '棚卸差異');

      const updated = await window.aivicApi.update(differenceTableIndex, id, {
        調整済フラグ: true,
        差異原因: reasonSelect.value,
        備考: adjustmentInput.value,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        // データ再読み込み
        const updatedDifferences = await window.aivicApi.list(differenceTableIndex);
        if (updatedDifferences) {
          tables[differenceTableIndex].records = updatedDifferences;
          currentData = createDifferenceData();
          renderRows(currentData);
        }
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const INVENTORY_TABLE = 3; // 在庫テーブル
  const HISTORY_TABLE = 4;   // 入出庫履歴テーブル
  const STOCKTAKING_DIFF_TABLE = 8; // 棚卸差異テーブル

  // 倉庫マスタから選択肢を動的生成
  const warehouseSelect = container.querySelector('#warehouse-select');
  if (tables[2] && tables[2].records) {
    tables[2].records.forEach(warehouse => {
      if (warehouse.有効フラグ) {
        const option = document.createElement('option');
        option.value = warehouse.倉庫コード;
        option.textContent = warehouse.倉庫名;
        warehouseSelect.appendChild(option);
      }
    });
  }

  // 在庫実績一覧の再描画関数
  function renderInventoryRows(rows) {
    const tbody = container.querySelector('#inventory-tbody');
    tbody.innerHTML = rows.map(row => {
      const productInfo = getProductInfo(row.商品ID);
      const warehouseInfo = getWarehouseInfo(row.倉庫ID);
      const statusColor = getStatusColor(row.在庫状態);

      return `
        <tr data-id="${row.在庫ID}" style="cursor: pointer;">
          <td>${productInfo.商品コード || ''}</td>
          <td>${productInfo.商品名 || ''}</td>
          <td>${warehouseInfo.倉庫名 || ''}</td>
          <td class="text-right">${row.現在庫数?.toLocaleString() || '0'}</td>
          <td class="text-right">${row.引当済数量?.toLocaleString() || '0'}</td>
          <td><span class="px-2 py-1 text-xs rounded" style="background: ${statusColor}; color: #fff;">${row.在庫状態 || ''}</span></td>
          <td>${formatDate(row.最終入庫日)}</td>
          <td>${formatDate(row.最終出庫日)}</td>
          <td>
            <button class="action-btn secondary text-xs px-2 py-1 history-btn" data-id="${row.在庫ID}" data-product-id="${row.商品ID}">履歴</button>
            <button class="action-btn secondary text-xs px-2 py-1 diff-btn" data-id="${row.在庫ID}" data-product-id="${row.商品ID}" data-warehouse-id="${row.倉庫ID}">差異</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummaryCards(rows);
  }

  // 商品情報取得
  function getProductInfo(productId) {
    if (!tables[1] || !tables[1].records) return {};
    return tables[1].records.find(p => p.商品ID === productId) || {};
  }

  // 倉庫情報取得
  function getWarehouseInfo(warehouseId) {
    if (!tables[2] || !tables[2].records) return {};
    return tables[2].records.find(w => w.倉庫ID === warehouseId) || {};
  }

  // 在庫状態の色分け
  function getStatusColor(status) {
    switch(status) {
      case '正常': return 'var(--primary)';
      case '欠品': return '#e74c3c';
      case '過剰': return '#f39c12';
      case '停止': return '#95a5a6';
      default: return 'var(--primary)';
    }
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // サマリーカード更新
  function updateSummaryCards(rows) {
    const currentStock = rows.reduce((sum, row) => sum + (row.現在庫数 || 0), 0);
    container.querySelector('#current-stock').textContent = currentStock.toLocaleString();

    // 入出庫履歴から集計
    if (tables[HISTORY_TABLE] && tables[HISTORY_TABLE].records) {
      const histories = tables[HISTORY_TABLE].records;
      const totalIn = histories.filter(h => h.入出庫区分 === '入庫').reduce((sum, h) => sum + (h.数量 || 0), 0);
      const totalOut = Math.abs(histories.filter(h => h.入出庫区分 === '出庫').reduce((sum, h) => sum + (h.数量 || 0), 0));

      container.querySelector('#total-in').textContent = totalIn.toLocaleString();
      container.querySelector('#total-out').textContent = totalOut.toLocaleString();
    }

    // 棚卸差異から集計
    if (tables[STOCKTAKING_DIFF_TABLE] && tables[STOCKTAKING_DIFF_TABLE].records) {
      const totalDiff = tables[STOCKTAKING_DIFF_TABLE].records.reduce((sum, d) => sum + Math.abs(d.差異数量 || 0), 0);
      container.querySelector('#inventory-diff').textContent = totalDiff.toLocaleString();
    }
  }

  // 初期データ表示
  if (tables[INVENTORY_TABLE] && tables[INVENTORY_TABLE].records) {
    renderInventoryRows(tables[INVENTORY_TABLE].records);
  }

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const productCode = container.querySelector('#product-code').value.trim();
    const productName = container.querySelector('#product-name').value.trim();
    const warehouseCode = container.querySelector('#warehouse-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    const rows = await window.aivicApi.list(INVENTORY_TABLE);
    if (!rows) return;

    let filteredRows = rows.filter(row => {
      const productInfo = getProductInfo(row.商品ID);
      const warehouseInfo = getWarehouseInfo(row.倉庫ID);

      if (productCode && !productInfo.商品コード?.includes(productCode)) return false;
      if (productName && !productInfo.商品名?.includes(productName)) return false;
      if (warehouseCode && warehouseInfo.倉庫コード !== warehouseCode) return false;

      if (startDate) {
        const lastInDate = new Date(row.最終入庫日);
        if (lastInDate < new Date(startDate)) return false;
      }
      if (endDate) {
        const lastOutDate = new Date(row.最終出庫日);
        if (lastOutDate > new Date(endDate)) return false;
      }

      return true;
    });

    renderInventoryRows(filteredRows);
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#product-code').value = '';
    container.querySelector('#product-name').value = '';
    container.querySelector('#warehouse-select').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';

    if (tables[INVENTORY_TABLE] && tables[INVENTORY_TABLE].records) {
      renderInventoryRows(tables[INVENTORY_TABLE].records);
    }
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(INVENTORY_TABLE);
    if (!rows) return;

    const headers = ['商品コード', '商品名', '倉庫名', '現在庫数', '引当済数量', '在庫状態', '最終入庫日', '最終出庫日'];
    const csvData = rows.map(row => {
      const productInfo = getProductInfo(row.商品ID);
      const warehouseInfo = getWarehouseInfo(row.倉庫ID);
      return [
        productInfo.商品コード || '',
        productInfo.商品名 || '',
        warehouseInfo.倉庫名 || '',
        row.現在庫数 || 0,
        row.引当済数量 || 0,
        row.在庫状態 || '',
        formatDate(row.最終入庫日),
        formatDate(row.最終出庫日)
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...csvData].map(row => 
      row.map(field => `"${field}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `在庫実績_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 履歴ボタンクリック
  container.addEventListener('click', async (e) => {
    const historyBtn = e.target.closest('.history-btn');
    if (historyBtn) {
      const productId = historyBtn.dataset.productId;
      const productInfo = getProductInfo(productId);

      container.querySelector('#modal-product-info').textContent = 
        `${productInfo.商品コード} - ${productInfo.商品名}`;

      const histories = await window.aivicApi.list(HISTORY_TABLE);
      if (histories) {
        const productHistories = histories.filter(h => h.商品ID === productId);
        const historyTbody = container.querySelector('#history-tbody');
        historyTbody.innerHTML = productHistories.map(h => `
          <tr>
            <td>${new Date(h.処理日時).toLocaleString('ja-JP')}</td>
            <td><span class="px-2 py-1 text-xs rounded" style="background: ${h.入出庫区分 === '入庫' ? 'var(--primary)' : '#ff6a00'}; color: #fff;">${h.入出庫区分}</span></td>
            <td class="text-right">${h.数量?.toLocaleString() || '0'}</td>
            <td class="text-right">${h.処理前在庫数?.toLocaleString() || '0'}</td>
            <td class="text-right">${h.処理後在庫数?.toLocaleString() || '0'}</td>
            <td>${h.理由コード || ''}</td>
            <td>${h.備考 || ''}</td>
          </tr>
        `).join('');
      }

      container.querySelector('#history-modal').style.display = 'flex';
    }

    // 差異ボタンクリック
    const diffBtn = e.target.closest('.diff-btn');
    if (diffBtn) {
      const productId = diffBtn.dataset.productId;
      const warehouseId = diffBtn.dataset.warehouseId;
      const productInfo = getProductInfo(productId);
      const warehouseInfo = getWarehouseInfo(warehouseId);

      container.querySelector('#diff-product-info').textContent = 
        `${productInfo.商品コード} - ${productInfo.商品名}`;
      container.querySelector('#diff-warehouse-info').textContent = warehouseInfo.倉庫名;

      const diffs = await window.aivicApi.list(STOCKTAKING_DIFF_TABLE);
      if (diffs) {
        const productDiff = diffs.find(d => d.商品ID === productId && d.倉庫ID === warehouseId);
        if (productDiff) {
          container.querySelector('#diff-book-stock').textContent = productDiff.帳簿在庫数?.toLocaleString() || '0';
          container.querySelector('#diff-actual-stock').textContent = productDiff.実地在庫数?.toLocaleString() || '0';
          container.querySelector('#diff-quantity').textContent = productDiff.差異数量?.toLocaleString() || '0';
          container.querySelector('#diff-reason').textContent = productDiff.差異原因 || '';
          container.querySelector('#diff-notes').textContent = productDiff.備考 || '';
        }
      }

      container.querySelector('#diff-modal').style.display = 'flex';
    }
  });

  // モーダル閉じる
  container.querySelector('#close-history-modal').addEventListener('click', () => {
    container.querySelector('#history-modal').style.display = 'none';
  });

  container.querySelector('#close-diff-modal').addEventListener('click', () => {
    container.querySelector('#diff-modal').style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#history-modal').addEventListener('click', (e) => {
    if (e.target.id === 'history-modal') {
      container.querySelector('#history-modal').style.display = 'none';
    }
  });

  container.querySelector('#diff-modal').addEventListener('click', (e) => {
    if (e.target.id === 'diff-modal') {
      container.querySelector('#diff-modal').style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#history-tbody');
  let allHistoryData = [];

  // 商品マスタと倉庫マスタのマップを作成
  const productMap = new Map();
  const warehouseMap = new Map();

  if (tables[1] && tables[1].records) {
    tables[1].records.forEach(product => {
      productMap.set(product.id, product);
    });
  }

  if (tables[2] && tables[2].records) {
    tables[2].records.forEach(warehouse => {
      warehouseMap.set(warehouse.id, warehouse);
    });
  }

  // 履歴データを再描画する関数
  function renderHistoryRows(rows) {
    tbody.innerHTML = rows.map(row => {
      const product = productMap.get(row.商品ID) || {};
      const warehouse = warehouseMap.get(row.倉庫ID) || {};
      const processDate = new Date(row.処理日時).toLocaleString('ja-JP');
      const quantityColor = row.数量 >= 0 ? '#22c55e' : '#ef4444';

      return `
        <tr data-id="${row.id}" class="border-b hover:bg-opacity-50" style="border-color: var(--border);">
          <td class="px-3 py-2 text-sm" style="color: var(--text);">${processDate}</td>
          <td class="px-3 py-2 text-sm" style="color: var(--text);">${product.商品名 || ''}</td>
