            </span>
          </td>
          <td class="px-3 py-2 text-sm text-right font-medium" style="color: ${quantityColor};">
            ${row.数量 >= 0 ? '+' : ''}${row.数量 || 0}
          </td>
          <td class="px-3 py-2 text-sm text-right" style="color: var(--text);">${row.処理前在庫数 || 0}</td>
          <td class="px-3 py-2 text-sm text-right" style="color: var(--text);">${row.処理後在庫数 || 0}</td>
          <td class="px-3 py-2 text-sm" style="color: var(--text-muted);">${row.理由コード || ''}</td>
          <td class="px-3 py-2 text-sm">
            <button class="action-btn secondary text-xs px-2 py-1 detail-btn" data-id="${row.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(rows);
  }

  // サマリー情報を更新
  function updateSummary(rows) {
    const totalCount = rows.length;
    const inboundCount = rows.filter(r => r.入出庫区分 === '入庫').length;
    const outboundCount = rows.filter(r => r.入出庫区分 === '出庫').length;
    const adjustmentCount = rows.filter(r => r.入出庫区分 === '調整').length;

    container.querySelector('#total-count').textContent = totalCount;
    container.querySelector('#inbound-count').textContent = inboundCount;
    container.querySelector('#outbound-count').textContent = outboundCount;
    container.querySelector('#adjustment-count').textContent = adjustmentCount;
  }

  // 初期データを表示
  if (tables[4] && tables[4].records) {
    allHistoryData = tables[4].records;
    renderHistoryRows(allHistoryData);
  }

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const productSearch = container.querySelector('#product-search').value.toLowerCase();
    const warehouseFilter = container.querySelector('#warehouse-filter').value;
    const historyTypeFilter = container.querySelector('#history-type-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    try {
      const historyData = await window.aivicApi.list(4);
      if (historyData) {
        allHistoryData = historyData;

        let filteredData = historyData.filter(row => {
          const product = productMap.get(row.商品ID) || {};
          const warehouse = warehouseMap.get(row.倉庫ID) || {};
          const processDate = new Date(row.処理日時);

          // 商品名フィルタ
          if (productSearch && !product.商品名?.toLowerCase().includes(productSearch)) {
            return false;
          }

          // 倉庫フィルタ
          if (warehouseFilter && warehouse.倉庫名 !== warehouseFilter) {
            return false;
          }

          // 履歴種別フィルタ
          if (historyTypeFilter && row.入出庫区分 !== historyTypeFilter) {
            return false;
          }

          // 日付範囲フィルタ
          if (startDate && processDate < new Date(startDate)) {
            return false;
          }
          if (endDate && processDate > new Date(endDate + ' 23:59:59')) {
            return false;
          }

          return true;
        });

        renderHistoryRows(filteredData);
      }
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // CSVエクスポート機能
  container.querySelector('#btn-export').addEventListener('click', async () => {
