        const csvData = [
          ['処理日時', '商品名', '倉庫名', '処理種別', '数量', '処理前在庫', '処理後在庫', '理由', '備考']
        ];

        historyData.forEach(row => {
          const product = productMap.get(row.商品ID) || {};
          const warehouse = warehouseMap.get(row.倉庫ID) || {};
          const processDate = new Date(row.処理日時).toLocaleString('ja-JP');

          csvData.push([
            processDate,
            product.商品名 || '',
            warehouse.倉庫名 || '',
            row.入出庫区分 || '',
            row.数量 || 0,
            row.処理前在庫数 || 0,
            row.処理後在庫数 || 0,
            row.理由コード || '',
            row.備考 || ''
          ]);
        });

        const csvContent = '\uFEFF' + csvData.map(row => 
          row.map(cell => `"${cell}"`).join(',')
        ).join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `在庫履歴_${new Date().toISOString().slice(0, 10)}.csv`;
        link.click();
      }
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
    }
  });

  // 詳細ボタンのイベントハンドリング
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const historyId = detailBtn.dataset.id;
      const historyData = allHistoryData.find(h => h.id === historyId);
      if (historyData) {
        // 在庫入出庫登録画面に遷移（詳細確認用）
        window.showScreen('scr-1780995483399');
      }
    }
  });

  // 初期データ読み込み
  window.aivicApi.list(4).then(historyData => {
    if (historyData) {
      allHistoryData = historyData;
      renderHistoryRows(historyData);
    }
  });
}

function(container, apiUrl, tables) {
  const inventoryTable = tables.find(t => t.tableName === '在庫') || tables[3];
  const productTable = tables.find(t => t.tableName === '商品マスタ') || tables[1];
  const warehouseTable = tables.find(t => t.tableName === '倉庫マスタ') || tables[2];

  let allInventoryData = [];
  let allProductData = [];
  let allWarehouseData = [];

  // 再描画関数
  function renderInventoryRows(rows) {
    const tbody = container.querySelector('#inventory-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="padding: 20px; text-align: center; color: var(--text-muted);">該当する在庫データがありません</td></tr>';
      updateSummary([]);
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const product = allProductData.find(p => p.商品ID === row.商品ID) || {};
      const warehouse = allWarehouseData.find(w => w.倉庫ID === row.倉庫ID) || {};

      const stockLevel = getStockLevel(row.現在庫数 || 0, row.発注点 || 0);
      const statusBadge = getStatusBadge(row.在庫状態 || '正常');

      return `
        <tr data-id="${row.在庫ID || row.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${product.商品コード || '-'}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${product.商品名 || '-'}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${product.カテゴリ || '-'}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${warehouse.倉庫名 || '-'}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: ${stockLevel.color}; text-align: right; font-weight: 500;">${(row.現在庫数 || 0).toLocaleString()}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text); text-align: right;">${(row.引当済数量 || 0).toLocaleString()}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text); text-align: right;">${(row.発注点 || 0).toLocaleString()}</td>
          <td style="padding: 10px 12px; text-align: center;">${statusBadge}</td>
          <td style="padding: 10px 12px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${row.在庫ID || row.id}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(rows);
    updateLastUpdated();
  }

  function getStockLevel(currentStock, reorderPoint) {
    if (currentStock === 0) {
      return { level: 'out', color: '#ff4444' };
    } else if (currentStock <= reorderPoint) {
      return { level: 'low', color: '#ff8800' };
    } else {
      return { level: 'normal', color: 'var(--text)' };
    }
  }

  function getStatusBadge(status) {
    const statusConfig = {
      '正常': { bg: '#00aa44', text: '#fff' },
      '欠品': { bg: '#ff4444', text: '#fff' },
      '過剰': { bg: '#0088cc', text: '#fff' },
      '停止': { bg: '#666666', text: '#fff' }
    };
    const config = statusConfig[status] || statusConfig['正常'];
    return `<span style="background: ${config.bg}; color: ${config.text}; padding: 3px 8px; border-radius: 12px; font-size: 11px; font-weight: 500;">${status}</span>`;
  }

  function updateSummary(rows) {
    const total = rows.length;
    const outOfStock = rows.filter(r => (r.現在庫数 || 0) === 0).length;
    const lowStock = rows.filter(r => (r.現在庫数 || 0) > 0 && (r.現在庫数 || 0) <= (r.発注点 || 0)).length;
    const normalStock = total - outOfStock - lowStock;

    container.querySelector('#total-products').textContent = total.toLocaleString();
    container.querySelector('#out-of-stock').textContent = outOfStock.toLocaleString();
    container.querySelector('#low-stock').textContent = lowStock.toLocaleString();
    container.querySelector('#normal-stock').textContent = normalStock.toLocaleString();
  }

  function updateLastUpdated() {
    const now = new Date();
    container.querySelector('#last-updated').textContent = 
      `${now.getFullYear()}/${(now.getMonth()+1).toString().padStart(2,'0')}/${now.getDate().toString().padStart(2,'0')} ${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}`;
  }

  function populateDropdowns() {
    const warehouseSelect = container.querySelector('#select-warehouse');
    const categorySelect = container.querySelector('#select-category');

    // 倉庫選択肢を動的に追加
    const warehouses = [...new Set(allWarehouseData.map(w => w.倉庫名).filter(Boolean))];
    warehouses.forEach(name => {
      if (!warehouseSelect.querySelector(`option[value="${name}"]`)) {
        const option = document.createElement('option');
        option.value = name;
        option.textContent = name;
        warehouseSelect.appendChild(option);
      }
    });

    // カテゴリ選択肢を動的に追加
    const categories = [...new Set(allProductData.map(p => p.カテゴリ).filter(Boolean))];
    categories.forEach(category => {
      if (!categorySelect.querySelector(`option[value="${category}"]`)) {
        const option = document.createElement('option');
        option.value = category;
        option.textContent = category;
        categorySelect.appendChild(option);
      }
    });
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [inventoryData, productData, warehouseData] = await Promise.all([
        window.aivicApi.list(3), // 在庫テーブル
        window.aivicApi.list(1), // 商品マスタ
        window.aivicApi.list(2)  // 倉庫マスタ
      ]);

      allInventoryData = inventoryData || inventoryTable.records || [];
      allProductData = productData || productTable.records || [];
      allWarehouseData = warehouseData || warehouseTable.records || [];

      populateDropdowns();
      renderInventoryRows(allInventoryData);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      allInventoryData = inventoryTable.records || [];
      allProductData = productTable.records || [];
      allWarehouseData = warehouseTable.records || [];
      populateDropdowns();
      renderInventoryRows(allInventoryData);
    }
  }

  // 検索フィルター
  function filterInventory() {
    const productCode = container.querySelector('#input-product-code').value.toLowerCase();
    const productName = container.querySelector('#input-product-name').value.toLowerCase();
    const warehouse = container.querySelector('#select-warehouse').value;
    const category = container.querySelector('#select-category').value;

    const filtered = allInventoryData.filter(row => {
      const product = allProductData.find(p => p.商品ID === row.商品ID) || {};
      const warehouseData = allWarehouseData.find(w => w.倉庫ID === row.倉庫ID) || {};

      const matchProductCode = !productCode || (product.商品コード || '').toLowerCase().includes(productCode);
      const matchProductName = !productName || (product.商品名 || '').toLowerCase().includes(productName);
      const matchWarehouse = !warehouse || warehouseData.倉庫名=== warehouse;
      const matchCategory = !category || product.カテゴリ === category;

      return matchProductCode && matchProductName && matchWarehouse && matchCategory;
    });

    renderInventoryRows(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['商品コード', '商品名', 'カテゴリ', '倉庫名', '現在在庫数', '引当済数量', '発注点', '在庫状態'];
    const rows = allInventoryData.map(row => {
      const product = allProductData.find(p => p.商品ID === row.商品ID) || {};
      const warehouse = allWarehouseData.find(w => w.倉庫ID === row.倉庫ID) || {};

      return [
        product.商品コード || '',
        product.商品名 || '',
        product.カテゴリ || '',
        warehouse.倉庫名 || '',
        row.現在庫数 || 0,
        row.引当済数量 || 0,
        row.発注点 || 0,
        row.在庫状態 || ''
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', filterInventory);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#input-product-code').value = '';
    container.querySelector('#input-product-name').value = '';
    container.querySelector('#select-warehouse').value = '';
    container.querySelector('#select-category').value = '';
    renderInventoryRows(allInventoryData);
  });

  container.querySelector('#btn-refresh').addEventListener('click', loadInitialData);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 行レベル操作
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const inventoryId = detailBtn.dataset.id;
      window.showScreen('scr-1780995614537'); // 在庫照会画面
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentData = [];

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector('#result-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="text-center py-4" style="color: var(--text-muted);">データがありません</td></tr>';
      updateSummary([]);
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const varianceAmount = (row.差異数量 || 0) * (row.仕入価格 || 0);
      const statusBadge = getStatusBadge(row.調整済フラグ);
      const varianceClass = getVarianceClass(row.差異数量);

      return `
        <tr data-id="${row.id}" class="hover:bg-opacity-50" style="border-bottom: 1px solid var(--border);">
          <td class="py-2 px-3 text-sm" style="color: var(--text);">${formatDate(row.棚卸実施日)}</td>
          <td class="py-2 px-3 text-sm" style="color: var(--text);">${row.倉庫名 || ''}</td>
          <td class="py-2 px-3 text-sm" style="color: var(--text);">${row.商品コード || ''}</td>
          <td class="py-2 px-3 text-sm" style="color: var(--text);">${row.商品名 || ''}</td>
          <td class="py-2 px-3 text-sm text-right" style="color: var(--text);">${(row.理論在庫数 || 0).toLocaleString()}</td>
          <td class="py-2 px-3 text-sm text-right" style="color: var(--text);">${(row.実在庫数 || 0).toLocaleString()}</td>
          <td class="py-2 px-3 text-sm text-right ${varianceClass}">${formatVariance(row.差異数量)}</td>
          <td class="py-2 px-3 text-sm text-right ${varianceClass}">¥${Math.abs(varianceAmount).toLocaleString()}</td>
          <td class="py-2 px-3 text-center">${statusBadge}</td>
          <td class="py-2 px-3 text-center">
            <button class="action-btn secondary text-xs detail-btn" data-id="${row.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(rows);
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  function formatVariance(variance) {
    if (!variance || variance === 0) return '0';
    return variance > 0 ? `+${variance.toLocaleString()}` : variance.toLocaleString();
  }

  function getVarianceClass(variance) {
    if (!variance || variance === 0) return '';
    return variance > 0 ? 'text-red-600' : 'text-blue-600';
  }

  function getStatusBadge(isAdjusted) {
    if (isAdjusted) {
      return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(34, 197, 94, 0.1); color: #16a34a;">調整済</span>';
    } else {
      return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(239, 68, 68, 0.1); color: #dc2626;">未調整</span>';
    }
  }

  function updateSummary(rows) {
    const total = rows.length;
    const varianceCount = rows.filter(r => r.差異数量 && r.差異数量 !== 0).length;
    const totalAmount = rows.reduce((sum, r) => sum + Math.abs((r.差異数量 || 0) * (r.仕入価格 || 0)), 0);
    const unadjustedCount = rows.filter(r => !r.調整済フラグ && r.差異数量 && r.差異数量 !== 0).length;

    container.querySelector('#summary-total').textContent = total.toLocaleString();
    container.querySelector('#summary-variance').textContent = varianceCount.toLocaleString();
    container.querySelector('#summary-amount').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('#summary-unadjusted').textContent = unadjustedCount.toLocaleString();
  }

  // 2. 初期データ描画
  currentData = tables[5]?.records || []; // 棚卸実績テーブル
  renderRows(currentData);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dateFrom = container.querySelector('#search-date-from').value;
    const dateTo = container.querySelector('#search-date-to').value;
    const warehouse = container.querySelector('#search-warehouse').value;
    const productCode = container.querySelector('#search-product-code').value;
    const varianceType = container.querySelector('#search-variance-type').value;

    try {
      const allRows = await window.aivicApi.list(5); // 棚卸実績
      if (!allRows) return;

      let filteredRows = allRows.filter(row => {
        // 日付範囲フィルタ
        if (dateFrom && row.棚卸実施日 && new Date(row.棚卸実施日) < new Date(dateFrom)) return false;
        if (dateTo && row.棚卸実施日 && new Date(row.棚卸実施日) > new Date(dateTo)) return false;

        // 倉庫フィルタ
        if (warehouse && row.倉庫コード !== warehouse) return false;

        // 商品コードフィルタ
        if (productCode && (!row.商品コード || !row.商品コード.includes(productCode))) return false;

        // 差異区分フィルタ
        if (varianceType !== '') {
          const variance = row.差異数量 || 0;
          if (varianceType === '0' && variance !== 0) return false;
          if (varianceType === '1' && variance <= 0) return false;
          if (varianceType === '-1' && variance >= 0) return false;
        }

        return true;
      });

      currentData = filteredRows;
      renderRows(filteredRows);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // 4. クリアボタンのイベントリスナー
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#search-date-from').value = '';
    container.querySelector('#search-date-to').value = '';
    container.querySelector('#search-warehouse').value = '';
    container.querySelector('#search-product-code').value = '';
    container.querySelector('#search-variance-type').value = '';

    currentData = tables[5]?.records || [];
    renderRows(currentData);
  });

  // 5. CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', () => {
    if (!currentData || currentData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['棚卸実施日', '倉庫名', '商品コード', '商品名', '理論在庫数', '実地在庫数', '差異数量', '差異金額', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map(row => {
        const varianceAmount = (row.差異数量 || 0) * (row.仕入価格 || 0);
        const status = row.調整済フラグ ? '調整済' : '未調整';
        return [
          formatDate(row.棚卸実施日),
          row.倉庫名 || '',
          row.商品コード || '',
          row.商品名 || '',
          row.理論在庫数 || 0,
          row.実在庫数 || 0,
          row.差異数量 || 0,
          Math.abs(varianceAmount),
          status
        ].map(field => `"${field}"`).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `棚卸結果_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 6. 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 棚卸差異分析画面に遷移
      window.showScreen('scr-1780995516133');
    }
  });
}

function(container, apiUrl, tables) {
  let currentEditId = null;

  // 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#difference-tbody');
    tbody.innerHTML = rows.map(row => {
      const difference = (row.実地在庫数 || 0) - (row.理論在庫数 || 0);
      const differenceClass = difference > 0 ? 'style="color: #22c55e;"' : difference < 0 ? 'style="color: #ef4444;"' : '';

      return `
        <tr data-id="${row.id}">
          <td style="text-align: center;">
            <input type="checkbox" class="row-checkbox" data-id="${row.id}" style="accent-color: var(--primary);">
          </td>
          <td>${row.商品コード || ''}</td>
          <td>${row.商品名 || ''}</td>
          <td>${row.倉庫名 || ''}</td>
          <td style="text-align: right;">${(row.理論在庫数 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(row.実地在庫数 || 0).toLocaleString()}</td>
          <td style="text-align: right;" ${differenceClass}>${difference > 0 ? '+' : ''}${difference.toLocaleString()}</td>
          <td>${row.調整区分 || '未設定'}</td>
          <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${row.差異理由 || ''}">${row.差異理由 || ''}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${row.id}" style="font-size: 11px; padding: 4px 8px;">編集</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSelectedCount();
  }

  // 選択件数更新
  function updateSelectedCount() {
    const checkboxes = container.querySelectorAll('.row-checkbox:checked');
    const count = checkboxes.length;
    container.querySelector('#selected-count').textContent = count;

    let totalDiff = 0;
    checkboxes.forEach(cb => {
      const row = cb.closest('tr');
      const diffCell = row.cells[6].textContent.replace(/[+,]/g, '');
      totalDiff += parseInt(diffCell) || 0;
    });

    const totalElement = container.querySelector('#total-difference');
    totalElement.textContent = totalDiff > 0 ? `+${totalDiff.toLocaleString()}` : totalDiff.toLocaleString();
    totalElement.style.color = totalDiff > 0 ? '#22c55e' : totalDiff < 0 ? '#ef4444' : 'var(--text)';
  }

  // 初期データ描画
  renderRows(tables[5]?.records || []);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const warehouse = container.querySelector('#warehouse-filter').value;
    const productCode = container.querySelector('#product-code-filter').value;
    const productName = container.querySelector('#product-name-filter').value;

    const rows = await window.aivicApi.list(5);
    if (rows) {
      const filtered = rows.filter(row => {
        return (!warehouse || row.倉庫コード === warehouse) &&
               (!productCode || (row.商品コード || '').includes(productCode)) &&
               (!productName || (row.商品名 || '').includes(productName));
      });
      renderRows(filtered);
    }
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateSelectedCount();
  });

  // 行チェックボックス変更
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('row-checkbox')) {
      updateSelectedCount();

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.row-checkbox');
      const checkedCount = container.querySelectorAll('.row-checkbox:checked').length;
      const selectAllCheckbox = container.querySelector('#select-all');

      if (checkedCount === 0) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = false;
      } else if (checkedCount === allCheckboxes.length) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = true;
      } else {
        selectAllCheckbox.indeterminate = true;
      }
    }
  });

  // 編集ボタン
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      currentEditId = editBtn.dataset.id;
      const rows = await window.aivicApi.list(5);
      if (rows) {
        const row = rows.find(r => r.id === currentEditId);
        if (row) {
          container.querySelector('#edit-product-code').value = row.商品コード || '';
          container.querySelector('#edit-product-name').value = row.商品名 || '';
          container.querySelector('#edit-theoretical').value = row.理論在庫数 || 0;
          container.querySelector('#edit-actual').value = row.実地在庫数 || 0;
          container.querySelector('#edit-reason').value = row.差異理由 || '';

          // 調整区分設定
          const adjustmentType = row.調整区分;
          if (adjustmentType === '増加調整') {
            container.querySelector('input[value="increase"]').checked = true;
          } else if (adjustmentType === '減少調整') {
            container.querySelector('input[value="decrease"]').checked = true;
          } else if (adjustmentType === '修正') {
            container.querySelector('input[value="correction"]').checked = true;
          }

          container.querySelector('#edit-modal').style.display = 'block';
        }
      }
    }
  });

  // モーダル閉じる
  container.querySelector('#modal-cancel').addEventListener('click', () => {
    container.querySelector('#edit-modal').style.display = 'none';
  });

  // モーダル保存
  container.querySelector('#modal-save').addEventListener('click', async () => {
    const reason = container.querySelector('#edit-reason').value;
    const adjustmentRadio = container.querySelector('input[name="adjustment-type"]:checked');
    const adjustmentType = adjustmentRadio ? 
      (adjustmentRadio.value === 'increase' ? '増加調整' : 
       adjustmentRadio.value === 'decrease' ? '減少調整' : '修正') : '';

    const updated = await window.aivicApi.update(5, currentEditId, {
      差異理由: reason,
      調整区分: adjustmentType
    });

    if (updated) {
      container.querySelector('#edit-modal').style.display = 'none';
      const rows = await window.aivicApi.list(5);
      if (rows) renderRows(rows);
    }
  });

  // 確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('確定する項目を選択してください。');
      return;
    }

    if (!confirm(`選択した${checkedBoxes.length}件の差異を確定しますか？`)) {
      return;
    }

    // 選択された項目を確定済みに更新
    for (const checkbox of checkedBoxes) {
      await window.aivicApi.update(5, checkbox.dataset.id, {
        調整済フラグ: true
      });
    }

    alert('在庫確定が完了しました。');
    window.showScreen('scr-1780995584605'); // 在庫確定処理画面へ
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(5);
    if (rows) {
      const headers = ['商品コード', '商品名', '倉庫名', '理論在庫数', '実地在庫数', '差異数', '調整区分', '差異理由'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(row => {
          const difference = (row.実地在庫数 || 0) - (row.理論在庫数 || 0);
          return [
            `"${row.商品コード || ''}"`,
            `"${row.商品名 || ''}"`,
            `"${row.倉庫名 || ''}"`,
            row.理論在庫数 || 0,
            row.実地在庫数 || 0,
            difference,
            `"${row.調整区分 || ''}"`,
            `"${row.差異理由 || ''}"`
          ].join(',');
        })
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `在庫差異一覧_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    }
  });
}
